INSERT INTO `foods` VALUES (2, '安徽鸭叫跳', '安徽农家传统菜肴，营养丰富，风味独特。鸭肉细嫩软香，鲜咸辣醇，地道乡土风味。主料净鸭头;鸭翅;鸭脚;鸭胗;鸭肠调料蒜姜;葱段;干红椒;精盐;白糖;老抽;味精;料酒;胡椒粉;色拉油', '1．净鸭头、鸭翅、鸭脚、鸭胗、鸭肠改刀成块。2．锅上火滑油，留底油放入蒜、姜、葱段、干红椒炒香，下改刀后的鸭块煸炒，放料酒等调料调味，放适量清水烧熟即成。注意事项烧鸭时注意火候，汤汁适当；不要让汤汁煳锅，影响成菜口味。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (3, '安徽卤舌', '鲜猪舌500克，葱、姜各适量调味料绍酒500克，酱油50克，冰糖25克，五香料15克，盐少许', '1、猪舌洗净，煮至浮沫漂起捞出，刮去舌苔膜，洗净。五香料用布袋装好，扎紧袋口。2、砂锅内倒入绍酒、酱油、冰糖、盐、葱(打结)、姜(拍松)和五香料袋，放入猪舌煮至六成烂熄火。3、材料留锅中浸味。食用时取出猪舌，除去舌根骨，切片装碟即可。好吃伴侣卤制食物最好用深陡的大砂锅，第一次卤制时，原料可以多放，卤好后把香料取出，卤汁保存在砂锅中，备再次卤制食品时使用。不过卤汁如果不常用要隔一丽天烧滚一次，可以保持常年不坏。每卤制一次食品，原卤汁都应再加进一些酱油、绍酒和水，五香料袋也要下进去。五香料袋使用两三次就要换新的。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (4, '安徽名菜荷花鸡', '洋葱半个土豆半个鸡胸脯肉100克青豆多粒鸡蛋1个食盐2克胡椒粉、玉米油适量', '1.鸡胸脯肉剁成肉糜，加入一个鸡蛋黄，2克盐和少量的胡椒粉，搅拌均匀;2.土豆去皮蒸熟压成泥;3.圆形模具刷上一层玉米油，这样比较好脱模。把搅拌好的肉糜放入模具中，中间加适量土豆泥,再铺一层肉糜,在肉糜上面插入适量的青豆，做成莲蓬;4.入蒸锅中冷水蒸20分钟取出放在白盘子中间;5.取几把汤匙，把肉糜分别放入汤匙中用手指轻轻抹平，上热水锅蒸3分钟，再一个个轻轻地从汤匙中脱出，摆在莲蓬周围；6.将洋葱切成花瓣形,挑出比较漂亮成形的入煮开的热水中焯一下;7.将洋葱荷花瓣围在莲蓬周围;8.撒上焯熟的青豆作点缀；9.取一个小碗，加入色拉酱沙律汁调蘸酱;10.同荷花鸡一起端上餐桌，一道色香味俱全的佳肴就搞定了!', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (5, '豆花鱼', '草鱼1条，豆花。熟黄豆、熟大蒜头、辣椒段、葱、姜、豆瓣酱、料酒、白糖、陈醋胡椒粉、植物油各适量。', '1、将草鱼宰杀、去鳞、内脏洗净，从背部对剖，除去骨，头，皮，将净鱼肉片成厚片，鱼头劈开，去掉鱼牙待用。2、锅内注油烧热，下葱、姜爆锅，烹入料酒，加鱼头、鱼骨、水大火熬成鱼汤。3、锅内注少许油烧热，下入辣椒段、豆瓣酱、熟大蒜头炒香，放入鱼汤、料酒、白糖、陈醋、胡椒粉煮沸，滤渣后加入豆花煮入味，捞出倒入盆内，再将鱼片放入汤汁中煮熟，捞出盖在豆花上。中间撒上熟黄豆和葱花；锅内注少许油烧热，浇在鱼片上，淋上香油即可。小诀窍特点麻辣鲜香，滑爽细嫩。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (6, '土家干锅脆爽', '山蛰菜100克，五花肉50克。调料大蒜苗、洋葱各10克，红杭椒15克，姜末、蒜片、干尖椒各5克，香醋6克，鸡精5克，红油、葱油各10克，老抽3克，生抽、麻油各5克，十三香4克，猪油15克。', '1、五花肉切2厘米厚的片，红杭椒切丁，洋葱改刀成丝，大蒜苗改刀成马蹄片待用。2、锅上火，入猪油烧至五成热时，入姜末、蒜片中火爆香，放入五花肉片煸炒出香，烹入老抽、生抽、香醋调味，放尖椒、红杭椒丁炒香，倒入干蛰菜翻炒均匀，加鸡精、蒜苗、十三香，淋入红油。3、最后浇葱油起锅，装入垫有洋葱丝的干锅内，淋麻油上桌。风味干香脆爽，回味悠长。关键在炒制干锅时，不能久炒，要适当地滴一点水，保证山蛰菜不至于是软绵。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (7, '核桃鸡', '主料：鸡胸脯肉200克，核桃180克，辅料：鲜香菇20克，火腿20克，冬笋50克，鸡蛋清30克，调料：盐3克，味精1克，白砂糖3克，蚕豆淀粉10克，猪油20克，香油5克，黄酒15克', '1.鸡脯肉剔去白筋，片成4厘米见方的薄片；2.核桃去壳仁用温水泡发，剥去外皮；3.将核桃仁用油炸成浅黄色，倒入漏勺沥油后，晾凉；4.冬笋去壳，切掉老根，洗净，煮熟；5.鸡片放入碗里，加盐少量、黄酒5克轻轻拌匀，再加入鸡蛋清、干淀粉5克抓拌浆好；6.在每片鸡片上放一份核桃仁，包成直径2厘米的小圆球；7.香菇、火腿、熟笋切成锯齿状的片；8.炒锅置旺火上，放入熟猪油，烧至五成热，将核桃鸡上锅走油，见外皮发挺时，倒入漏勺沥去油；9.原锅留底油，放入香菇、笋片煸炒，加入50毫升鸡汤、白糖、盐适量、黄酒10克、味精，用湿淀粉10克（淀粉5克加水调匀）调稀勾薄芡；10.再加入火腿、核桃鸡球，颠翻两下，淋上香油，出锅装盘即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (8, '香茶熏鸡', '光鸡项1只(约750克)，花茶50克，香樟叶30克，松柏枝20克，黄片糖100克，姜块50克，葱节20克，姜茸、葱粒、蒜茸各30毫克，盐1茶匙，味精1茶匙，胡椒粉1/3茶匙，香油1/2茶匙，生抽2茶匙', '1、将鸡洗后，放入精卤锅中用小火浸煮至刚熟捞起。2、起锅放入花茶、香樟叶、松柏枝、黄片糖等炒香起烟，放入鸡加盖密封好。3、用小火熏至鸡皮呈金黄色取出(斩件装盘)，跟味碟上席。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (9, '酒卤鸭', '主料：鸭2100克，调料：盐10克，白皮大蒜200克，姜10克，黄酒200克，玉米淀粉5克，胡椒粉1克，猪油100克', '1.鸭宰杀治净，将净鸭从翅下开一刀口，取出内脏，剁去翅尖、脚爪和嘴壳，洗净；2.将精盐5克放小碗内，加水少许溶化，抹遍鸭身；3.姜洗净，切碎，用纱布过出姜水，入锅内入烧开，捞出姜茸不要，做成姜汁；4.取一半姜汁放碗内，加入精盐适量和黄酒50克，溶化后倒进鸭肚内；5.把整理好的鸭放入汤碗中，上笼蒸至八成烂时取出，原汤汁留碗中备用；6.炒锅置旺火，放入熟猪油，烧至七成热，将鸭下锅炸至淡黄色，捞出沥油；7.蒜瓣洗净放在盘内；8.将炸好的鸭剁成0.7厘米宽、5厘米长的块，鸭头一劈两开，摆在蒜瓣上，鸭脯向上，仍码成整鸭形状，再上笼蒸至酥烂；9.锅置中火上，放入鸭汤150毫升、精盐2.5克、黄酒适量、剩余姜汁，烧至酒香刚出时，用湿淀粉调稀勾薄芡，熟猪油10克浇在鸭上；10.将蒸鸭的原汤浇入锅中，加鸭汤350毫升烧开，盛入汤碗内，撒上少许胡椒粉，随鸭一起上桌。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (10, '葱油牛蹄筋', '主料：水发牛蹄筋配料：油菜心，调料：盐，鸡精，料酒，葱段，姜丝，蚝油，胡椒粉，水淀粉，食用油，高汤，葱油', '1、将水发牛筋切成段，用沸水焯一下，油菜心洗净用沸水加盐、食用油汆烫熟后取出，转圈码放在盘子四周；2、坐锅点火，倒入油，三成熟时下葱段炒出葱香味时倒出适量的葱油，再放入姜丝、盐、料酒、胡椒粉、老抽、鸡精、白糖、高汤、牛蹄筋转小火煨炖30分钟，蹄筋软烂至汁浓时，转大火用水淀粉勾芡，淋入葱油，浇在盘中即可食用。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (11, '酥炸凤翼', '主料：鸡翅400克，辅料：糯米15克，火腿15克，芝麻20克，面包屑50克，鸡蛋120克，调料：盐1克，黄酒15克，椒盐5克，小麦面粉10克，小葱3克，玉米淀粉13克，姜3克，花生油75克', '1.先把鸡翅膀的翅尖一个个地剁掉，再于骨节弯曲处剁成两段，放在碗里；2.鸡翅段的碗里加入葱、姜（拍松）和黄酒，上笼蒸至七成烂，取出晾凉；3.晾凉后在每个鸡翅上横划一刀，剔去骨；4.糯米淘净，用冷水浸泡，上笼蒸熟；5.净芝麻炒至微黄有香味，出锅碾碎；6.熟火腿切末；7.将糯米、芝麻、火腿、盐一起搅拌均匀，做成馅心；8.鸡蛋磕在碗里搅散，加湿淀粉、面粉调成糊；9.在鸡翅骨的空隙处，一个个瓤上馅心，外面裹上一层蛋糊，再滚上一层面包屑，摆在盘中；10.炒锅置旺火上，放入熟猪油，烧至六成热时端离火口，将鸡翅逐个下锅，待全部下完后，把锅端回火上，炸至浅黄色，捞出装盘，撒上花椒盐即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (12, '腌鲜鳜鱼', '净鲜鳜鱼(桂鱼)1条约650克，猪五花肉、熟笋片各50克，姜末、青蒜段各25克，白糖、湿淀粉各2茶匙，绍酒3茶匙，酱油2汤匙，上汤3杯，熟猪油75克', '1、鳜鱼身两面各割几条斜刀花纹，放在风口处晾干。2、锅置大火上，放入熟猪油(60克)，烧至七成熟时，将鱼下锅煎至两面呈淡黄色时盛出。3、原锅中留少许油，下肉片、笋片略煸后，将鱼放入，加酱油、绍酒、白糖、姜末和上汤、用大火煮滚，再改用小火煮40分钟左右。4、待汤汁将干时，洒上青蒜，用生粉水勾薄芡，淋上熟猪油15克起锅即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (13, '蛋饺', '鸡蛋，猪肉末，盐，米酒，生抽，白胡椒粉，香油，姜，葱', '1、肉末加鸡蛋搅拌上劲。2、加入盐、米酒、生抽、白胡椒粉、香油、姜葱顺一个方向拌匀。3、再准备4个鸡蛋打散。4、不锈钢勺子加热，刷一层薄油。5、倒入两勺蛋液，转动勺子。6、使蛋液成均匀的蛋皮。7、放一勺肉末在蛋皮的一侧。8、蛋皮的另一侧用小勺子轻轻叠起来，形成饺子形。9、再小火稍微加热，使蛋饺形状固定。10、一次性吃不完可放急冻，随吃随取。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (14, '蜜汁梅花肉', '梅花肉，蜜汁叉烧酱，黄瓜，生抽，老抽，白砂糖，料酒，白胡椒粉，鸡精，姜', '1.梅花肉用一汤匙料酒、半汤匙生抽、半汤匙老抽、半汤匙白砂糖、一汤匙蜜汁叉烧酱、少许白胡椒粉、鸡精和姜丝拌匀2.放入密封保鲜盒中，入冰箱腌制24小时3.黄瓜擦成丝铺在盘底备用4.双立人STAUB珐琅铸铁平底锅小火预热两分钟5.锅中倒入少许食用油，烧热后，把腌制好的梅花肉平铺在锅中6.小火，煎好一面再翻过来把另一面煎熟。把煎好的梅花肉放在有黄瓜丝垫底的盘子中。腌制梅花肉的汁，挑出姜丝，倒入锅中煮沸后，吃的时候浇在肉的表面', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (15, '鸭双味', '主料：鸭肉500克，鸭掌300克，辅料：鸡蛋150克，小麦面粉50克，调料：料酒25克，小葱10克，辣椒油5克，姜25克，香油15克，白皮大蒜10克，猪油75克，盐15克，味精1克', '1.鸭肉（鸭小腿）放碗内，加精盐5克、料酒腌渍1小时入味。2.姜10克切片、15克切丝，葱切丝。3.将腌好的鸭腿加入葱片、蒜瓣5克上笼蒸烂取出待用。4.另将鸡蛋磕在碗内，加面粉搅蛋糊，再加香油搅匀。5.鸭掌煮至七成烂捞出，剔去骨，趁热用辣椒油、味精、白糖、精盐10克、蒜瓣5克（拍碎）拌匀，堆放在盘中间。6.锅置旺火上，倒入熟猪油，烧至五成热，将鸭小腿逐个滚上蛋糊，下油锅炸至金黄色时捞起，摆放在鸭掌的周围，葱、姜丝分别放在盘的两边即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (16, '花茹田鸡', '田鸡腿，水发花菇，姜汁，味精，甜米酒', '1、鸡腿在开水中焯一下后沥干，用姜汁、精盐、甜米酒、味精腌渍入味。2、将田鸡腿排列在碗中，花菇放在田鸡腿上面，加入猪油、鸡汤，另用一只盘子盖好，上笼旺火蒸15分钟后取出花菇。3、将田鸡腿翻扣在盘中，花菇排在四周，锅中汤烧开后用湿淀粉够薄芡，淋入猪油浇在盘中即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (17, '问政山笋', '主料：净问政山笋(或春笋)500克，辅料：水发香菇50克，香肠50克，火腿骨l条，调料：香油，生粉，白糖各适量', '1.将问政笋切成滚刀块。香肠、香菇(厚菇)切片。2.将切好的笋块放入砂锅中，加火腿骨和水(淹没笋)，用大火煮滚后改用小火炖15分钟。3.将炖好的笋放另一锅中，加入香肠、香菇、白糖、盐翻炒片刻，待汤汁烧干时，取出火腿骨，再用生粉水勾芡，淋上香油即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (18, '松子鸭颈', '主料：烤鸭皮，松子，辅料：香菜，虾肉，调料：精盐，绍酒，葱姜汁，味精，蛋清，干淀粉，花生油', '(1)将烤鸭片下，切成5厘米宽，6厘米长的块待用。虾仁、肥膘分别斩成茸，放入碗内加精盐、绍酒。葱姜汁、味精及蛋清搅拌成虾馅。(2)将松子下四成热(约100℃的油锅拉油，变色时倒出沥油，放入虾馅内拌匀。将鸭皮(皮面朝下)摊在砧板上，拍上干淀粉，放上虾馅，卷成5厘米长的鸭颈，锅上火烧热，倒入花生油，烧至五成热(约125℃)时，将鸭卷徐徐投入锅中炸至皮脆色金红，然后捞出装盘，以香菜衬托即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (19, '蜜汁红芋', '红芋1000克，蜂蜜200克，冰糖125克', '1、选出过汗的聚橘黄色红芋洗净去皮，消成两头尖的块；2、砂锅底部放竹箅加水、放冰糖放入火上熬划，再放入红芋、蜂蜜，烧开后移小火焖1小时；3、汤汁浓缩后，将红芋装盘，浇上原汁即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (20, '鱼羊炖时蔬', '主料：鱼头150克，羊肉馅150克，辅料：油菜心，白萝卜，粉丝，调料：盐，料酒，胡椒粉，鸡精，鸡蛋，淀粉，香菜叶，食用油，葱丝，姜丝', '1、将鱼头焯水备用，羊肉馅加盐、料酒、盐、鸡精、胡椒粉、鸡蛋、淀粉搅拌均匀备用；2、将油菜心、白萝卜、香菜分别洗净切好备用；3、坐锅点火倒少许油，放葱姜丝煸炒一下，放入鱼头烹少量料酒，加清水大火煮沸，再放入白萝卜，挤入丸子，中火煮片刻后加盐、鸡精、胡椒粉、调味，放入油菜心和粉丝煮熟撒上香菜即可出锅。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (21, '葱香鲫鱼', '材料鲫鱼2条。配料香叶、桂皮、八角、姜、葱。调料盐、味精、酱油、糖、陈醋。', '1．将鲫鱼去鳞、内脏、腮，打上柳叶刀，用盐、味精、葱、姜、料酒味口。2．炒锅坐油烧至七八成热，将鲫鱼下锅炸成金黄色，捞出。3．锅内打底油，下入葱、姜、香叶、桂皮、八角炒出香味，加入盐、味精、酱油、糖、陈醋烧开，打去浮沫，下入大葱垫底，再加入炸好的鲫鱼，用小火(火靠)熟出锅即可。4．出锅的时候在鲫鱼的上面淋上红油。提示肉嫩骨酥，酸甜可口，葱香十足。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 1, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (22, '＜鲁菜＞酱炒青蟹', '\"「主　料」雄性青蟹（红蟳）3只约1200g\",\"「辅　料」甜面酱75g\",\"葱1根\",\"姜1块\",\"大蒜4粒\",\"香菜少许\",\"「辅　料」绍兴花雕酒80mL\",\"高汤120mL\",\"花椒油20mL\",\"小麦粉适量\",\"白砂糖1大匙\",\"食盐1大匙\"', '1:红蟳腹部向上，用尖刀或筷子刺入脐盖顶部（新手可以先刺杀再松绑，防止被夹伤）；2:再翻过来，腹部向下，切除脚尖；3:掀开蟹壳，剪掉蟹鳃、口器，摘除蟹胃，撕去脐盖；4:剪掉壳外的眼睛、触角以及多余的外边缘，清除壳内污物，把蟹壳和躯干内外刷洗干净；5:切下蟹钳和蟹脚，用刀面拍破；6:躯干纵向、横向各一刀，分成4块；7:蟹钳、蟹脚、躯干和蟹壳裹上小麦粉待用；8:葱、姜、蒜均切成细末；香菜洗净，去除老梗、黄叶和根部，切成2cm见长的小段；9:油锅烧至五～六成热，投入裹好小麦粉的蟹块炸成金黄色，捞出、沥油；10:锅内留底油，烧至三～四成热，放入葱、姜、蒜末炒香，加入甜面酱炒匀，再加入花雕酒、高汤、白砂糖和食盐烧开；11:投入炸好的蟹块翻炒，充分入味后淋入花椒油起锅；12:入碗摆整齐，撒上香菜即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (23, '美容鲁菜——水晶肘子', '带皮的猪肘子1个（约1500克），肉皮250克，葱段、姜片共50克，精盐5克，料酒20克，味精2克，清汤1500克', '1.将值猪肘子刮洗干净，从中间劈开。肉皮也刮洗干净。然后将肘子和肉皮放入汤锅内煮至五成熟时捞出，剔去肘子骨，切为两块。肉皮用刀片去肥肉膘，切成细丝。花椒用菜叶包起来。2.取干净盆放入肘子肉，撒上肉皮丝，和上葱段、姜片、花椒、料酒、精盐、味精，将清汤烧沸后，撇去浮沫，浇在肘子盆内，上笼用旺火将肘子蒸烂后取出，挑去葱姜、花椒，晾晾后切成块或片装盘即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (24, '老济南大米干饭把子肉', '五花肉，鸡蛋，大米，老抽，生抽，大葱，姜，花椒，八角，桂皮，白糖，食用油', '1、将五花肉切成5-10厘米厚的扇面，浸入老抽和白糖，腌制一夜。2、将五花肉放在案板或盘子里晾一小时左右，但切记留下腌制使用的汤汁。在此期间可以用白水煮几个鸡蛋并准备调料。3、用牙签横向穿入五花肉，避免烹饪过程中肉散开。4、食用油（花生油最宜）入锅加热，依次把肉放入，炸至三四成熟。5、炸完肉后，可以依次敲几个鸡蛋进去，炸鸡蛋也是把子肉里很出名的一部分。6、将腌制使用的老抽汤汁倒入煮锅，加入大葱段、姜片、各种调料。7、汤汁开锅，放入五花肉、煮鸡蛋、炸鸡蛋、适量增加水和老抽，使汤汁略微没过食材。盖上锅盖闷半小时到一小时即可。8、蒸米饭，水应比平时少加一些，这样米饭比较干。享用时记得把煮肉的汤汁淋在米饭上！', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:52', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (25, '经典鲁菜', '主料：冬笋香菇调料：葱，姜，盐，酱油，胡椒粉，加饭酒，白糖，淀粉，食用油', '1、冬笋最好取尖，因为嫩。切成小梳子角洗净，里边有白渣子一定清干净，多过几遍水，用水泡一会儿，然后焯两遍水捞出来泡凉水备用。2、香菇最好凉水泡一夜，来不及用热水泡透去蒂备用，整个或者斜片一下都可。3、腌汁：坐锅下一点油烧热，下两小截葱段、几片姜片炒香，然后热锅放酱油爆香，下一点加饭酒，然后下水（鸡汤更好），以能没过原料为好。然后放少许盐、糖、胡椒粉，把两种处理好的原料放入煮开，关火泡一会儿。4、开烧：锅放一点油，放10克左右的白糖炒糖色，炒至紫红色放入捞出的二冬，快速炒至上色。然后放少许酱油、加饭酒、胡椒粉、少许盐（因为已经泡过有底味了，万不可多放盐），然后下汤或者水，漫到原料的多一半就可以了。5、中火烧到汤汁还剩三成的时候放水淀粉，大火炒到上劲点些明油，装盘。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (26, '山东名吃-美味油旋做法', 'full-purpose面粉，南德调味料，盐，植物油', '第一步：活面，一半冷面，一半烫面；第二部：把面擀成一个大圆饼，在圆饼的上半部分，撒上盐、五香粉或南德调料、植物油，摸匀；第三步：把饼对折，不要完全对折，没摸调料的那部分离边缘差两指宽的缝；第四步：在外面的半层继续摸盐、五香粉、植物油；第五步：重复以上动作，再折两次。最后，成为一个长条之后，把长条卷成一个圆圈，摁成一个饼；然后用擀面杖擀大。锅里少放油，铺满平底锅锅底，将饼放入，一面炸的差不多，再翻个个。差不多就可以出锅了', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (27, '正宗山东打卤面！！', '面粉我用的是CAKEFLOUR，属于低筋面粉；材料：黑木耳，黄花菜，鸡蛋，蘑菇（最好是蓁蘑，我没有就用普通的WHITEMUSHROOM代替了，味道也很不错！），咸肉（没有的话也可以用普通的五花肉代替），葱末，还有姜丝适量。', '基本上面和水的比例是2：1，如果加鸡蛋，水就要相对的再少一些，手杆面的面要和得硬一些，比较有嚼劲而且下锅后不会变成面汤！面和好了（和面的最高境界：面光，手光，盆光），铺上抹布或盖上盖子醒30分钟，期间可以准备卤。接着是卤的部分：材料：黑木耳，黄花菜，鸡蛋，蘑菇（最好是蓁蘑，我没有就用普通的WHITEMUSHROOM代替了，味道也很不错！），咸肉（没有的话也可以用普通的五花肉代替），葱末，还有姜丝适量。步骤1：黑木耳和黄花菜要用热水泡发，然后木耳切碎，黄花菜去根切段，蘑菇切片，五花肉切丁，待用；步骤2：鸡蛋打散，炒鸡蛋，鸡蛋炒好放到旁边待用；步骤3：葱末姜丝爆锅加入肉丁翻炒；步骤4：加入木耳和黄花菜，大约5分钟后加入蘑菇步骤5：最后再加入之前炒好的鸡蛋，勾芡出锅。----------------------------------华丽分割，再回到面的部分----------------------------------------这时候面已经醒好了，步骤1：把大面团分成手掌大的若干小份，取一份杆成面饼步骤2：面饼上多撒匀面粉，折叠起来步骤3：用刀把折好的面饼均匀切成小条步骤4：把面条抻开，就可以下锅煮了！煮好的面浇上之前做好的卤，再加上酱牛肉，多美的一顿饭啊~吃着都感动！小诀窍一定要多放酱油，酱油味道重才好吃！P.S.也可以在煮面的时候做卤，这样卤就不会凉了！', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (28, '山东炒肉', '大白菜，猪里脊，胡椒粉，酱油，姜，香菜', '1.大白菜去掉叶子，把白菜绑切成梭型的细丝。猪里脊切成细丝，加入盐，酱油腌制一会儿。2.锅内加少许底油，放姜和胡椒粉炸香，倒入肉缄炒熟加入白菜丝翻炒，倒入一些清淡稍收汁即可。3.出锅前加盐，香菜。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (29, '山东包子', '主料：发面500克，猪肉，香菜，300克，水鹿角菜各50克，嫩白菜帮100克。调料　香油25克，碎葱50克，味精3克，盐2克', '(1)把白菜猪肉都切成小丁，放入盆中，加入鹿角菜(洗净后切成小段)、碎葱、姜末、香菜末、盐、香油、味精和黄酱拌匀，把味调好制成馅。(2)把发面对好碱分成30个剂子，用面杖擀成皮，把馅放在皮中捏20余个摺包好。把包好的包子先放10分钟醒一下，然后上屉用旺火蒸10分钟即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (30, '山东狮子头', '白馒头400公克，葱末25公克，姜末15公克，蒜末20公克，盐6公克，细砂糖25公克，酱油35公克，香油20公克，水200公克，冰糖30公克，八角2粒', '1.白馒头先撕碎用水泡软备用。2.将作法1的白馒头及所有肉馅材料B的材料搅拌均匀至呈黏稠胶状，放入冰箱冷藏。3.冷藏过后的肉馅直接用手搓成圆扁状的狮子头。4.取一平底锅，，热油锅，再将狮子头逐一放入，以小火至中火煎至两面都金黄色时即可取出。5.将卤汁材料一同放入锅中煮滚，再将作法4的狮子头放入卤汁中卤约35分钟即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (31, '山东焖烧鸡', '鸡腿肉，姜，八角，生抽，米酒，（葱），干辣椒', '1、鸡腿肉切小块儿备用。2、热锅下油，用五六个姜片炝锅，姜片变金黄色后加入鸡腿肉拌炒。3、至鸡皮开始紧缩的时候加几个八角，再加两汤匙米酒、两到三汤匙生抽、少许糖，可以吃辣的加些干辣椒，然后转小火，盖盖子开始焖烧。期间可以开盖略搅拌，再焖5分钟即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (32, '山东抓果', '主料：面粉、鸡蛋辅料：酵母、芝麻调料：白糖、食用油', '1、酵母用少许温水稀释开。把稀释好的酵母倒入盆内。打入两个鸡蛋。2、加入白糖。倒入食用油。用打蛋器把所有材料充分打匀。3、一点点的加入面粉，边加边用筷子搅拌。搅拌成面团。用手将面团揉光滑，揉的过程中再加入适量干面粉，尽量将面团和的硬一些，容易成型。4、盖上保鲜膜或者盖子，放在温暖处，饧发。面团发至原来面团的一倍就可以了，上午和面，吃了个中午饭，就满满一盆了。将饧发好的面团取出，排气，揉光滑。5、炒熟的白芝麻放进去，与面团揉匀。将揉好的面团用擀面杖擀成面片，约0.5cm左右。用刀将面片切成菱形块，饧发半小时(也可用模具刻出自己喜欢的造型)。6、电饼铛接通电源，调为小火，饧发好的菱形块放上去。一面成型后，翻面，直至煎至两面金黄，口感酥脆即可。小诀窍依次把所有的抓果烙完，凉晾后会更加的香脆。如一次性吃不完，凉晾后用保鲜袋密封好保存，不易受潮。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (33, '山东白菜泡菜', '山东白菜3颗，韭菜10根，1.盐1/2杯，2.辣油1/2大匙，辣椒酱2大匙，糖1大匙', '(1)将山东白菜剥除3∼5片表面叶片后，取山东白菜心及嫩叶洗净沥干水份备用。韭菜洗净沥干切成5公分长段备用。(2)将调味料(1)均匀撒在山东白菜叶片上，并用手轻轻加以搓揉使之软化，待山东白菜出水，盐水可盖过大部份白菜时即可静置腌渍，约半天后再将盐水倒掉，略用冷开水洗净沥干水份，切成5公分长段备用。(3)将调味料(2)与韭菜混合均匀后加入山东白菜中搅匀，加盖置于阴凉处腌渍约1∼2天即可食用，冷藏约可保存2週。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (34, '山东烧鸡', '\"鸡腿?3只\",\"油（或橄榄油）1小匙\",\"葱4根\",\"大蒜整粒5粒\",\"大蒜切丁5颗\",\"米酒（可不用）1匙\",\"花椒粒或辣椒（可不用）看个人\",\"姜片5片\",\"小黄瓜1条\",', '1:醃鸡腿：鸡腿洗干净，整只放到小锅子中，倒入一大匙酱油，静置15分钟。鸡腿上色：拿出平底锅，倒入一点油，将醃好的鸡腿，放置平底锅上，中火煎至表面有卤鸡腿那种颜色，即可拿起。（此时里面的鸡腿肉还没熟）电锅蒸鸡腿：把煎好的鸡腿，放置锅子中加入葱段一些、拨好的大蒜5颗（整粒）、姜片3小片、此时也可以放入辣椒或花椒粒增加香气，如果有米酒，可加一匙去腥。电锅外锅放1.5杯水，就开始蒸。2:电锅跳起来后，再闷5分钟才打开。捞起来鸡腿后，把鸡腿拨成丝状。（肉就准备完成）3:小黄瓜洗干净后切成一段一段,每段约3cm.接下来把小黄瓜切成块状如图。4:（1）拿出5颗蒜头，切成蒜末（2）葱切成葱丝（3）姜2片磨成姜末以上三种混合在一起，放入碗中。（4）加一大匙酱油、一大匙酱油膏、一大匙乌酢进入碗中。5:舀一匙刚才蒸鸡腿内锅的肉汁，放入步骤六的酱料，混合缴一缴，增加酱汁的香气。此时，酱料就会看起来有些油亮油亮6:把鸡腿肉丝舖在小黄瓜上面7:再把酱汁倒入，大功告成！', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (35, '山东小喜饼', '\"中筋面粉560g\",\"酵母粉8g\",\"奶粉18g\",\"香草粉2g\",\"糖82g\",\"盐1g\",\"酥油(或沙拉油)64g\",\"蛋4颗\",\"水102g\"', '1:将粉类、糖、盐、蛋以钩型搅拌器拌匀。2:搅拌至无粉末，加入酥油。3:拌匀后每次加入水，每次要等水融进面团后才可再加入新的水。4:搅拌至成团光滑。5:整圆后盖锅盖，基本发酵30分钟。6:分割成20颗，每颗50g。滚圆后，盖锅盖，中间发酵15分钟。7:将小面团撖平，盖锅盖，最后发酵20分钟。8:不沾锅抹一层薄油热锅，将小喜饼压扁，干烙至2面金黄即可。9:立在锅边，煎侧面，上色后起锅。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (36, '山东烧鸡', '\"去骨鸡腿肉2片\",\"小黄瓜2-3条\"', '1:将去骨鸡腿肉浸泡在酱油及少许绍兴酒中，进冰箱醃一个晚上。2:隔天将鸡肉取出，把酱油擦乾，用平底锅下一些油，鸡片朝下置入，以半煎炸的方式煎到鸡皮酥脆。3:鸡肉不需全熟，撒上葱白及花椒、姜片、八角，进电锅，外锅两杯水蒸至跳起，再续闷15分钟取出放凉，蒸好的鸡汁过滤后备用。4:白醋、乌醋、酱油、蒜末、辣椒末、葱花、鸡汁、糖跟香油拌匀，即完成淋酱。辣油及花椒油可看个人喜好添加。5:小黄瓜拍碎，铺于盘底备用。6:放凉的鸡肉用手撕成一片片备用。7:盘底依序铺上黄瓜及鸡丝冰存，上桌前淋上淋酱及香菜叶，准备惊艳全场?', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (37, '山东白菜卤', '山东大白菜半颗,香菇3朵,虾米少许,红萝卜1/4条,玉米笋4根,黑木耳3大朵,金针菇1包,油葱25g,盐巴2匙', '1、白菜洗净切大块先下热水中煮2、香菇/红萝卜/玉米笋/黑木耳切丝,金针菇洗净备用3、白菜煮软后,将作法2的材料及虾米全部下锅中煮约10分钟4、加入油葱及盐巴调味,续煮10分钟即可', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (38, '海景山东青', '\"山东白菜200克\",\"菠菜600克\",\"虾皮少量\",\"蒜头切末少量\",\"白胡椒粉少量\",\"料理油1茶匙\",\"香油1/3茶匙\",\"盐少许\",', '虾皮洗干净,蒜头切末,混合备用;山东白菜,菠菜洗净,切妥备用。料理油入炒锅,中小火热锅将假皮+蒜末下锅,炒至蒜头微黄(可以闻到虾香和蒜香)。将山东白菜加入锅内,轻拌,盖锅盖约2分钟(待白菜变软,微微出水)锅盖打开后,将菠菜加入,加盐轻轻拌炒至菠菜转稍软,即可关火,加胡椒粉,香油,再轻轻拌一下即可盛盘', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (39, '油葱爆皮卤山东白', '\"山东白1.5颗\",\"红萝卜片1/2条\",\"爆皮1小包\",\"泡软香菇10朵\",\"盐少许\",\"胡椒粉少许\",\"蒜片2颗\",\"红葱头酥1-2大匙\"', '1:备料(香菇泡软一切二,山东白切大块,红萝卜切片备用)2:起1大匙猪油爆香蒜片3:再放入红萝卜片及香菇片爆香4:放入山东白菜块5:再放入爆皮块闷煮约10-15min左右,放点盐及胡椒粉调味即可,起锅再放入红葱头酥醍味6:成品上桌', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (40, '山东馒头版法国吐司', '\"山东馒头1颗\",\"蛋2个\",\"牛奶少许\",', '1:将已解冻的山东馒头切成片状，再切成一口大小。2:将蛋打匀加入牛奶后再打散；牛奶的用量不要太多即可。打好的蛋奶汁加入切好的山东馒头中浸泡。3:等馒头吸收好蛋奶汁后，在平底锅上倒适量的橄榄油（也可以用奶油）开始煎馒头，记得开小火将两面煎到有点金黄色就可以起锅。4:最后看个人喜好淋上蜂蜜或果酱，什么都不加也有炸馒头的香脆和法国土司的绵密口感。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (41, '山东大枣金针花结排骨汤', '\"山东大枣(红枣)5颗\",\"金针花1碗\",\"苟杞1大匙\",\"排骨5人份\",\"海盐酌量\",\"鲜味炒手酌量\"', '1:准备好以上食材2:取出适量食材3:将金针先泡点水，不易断比较好打结4:打结好的金针花结5:先将排骨川烫6:取适量的水并将川烫后的排骨放入炖锅7:利用叉子将红枣叉数个洞，放入锅内8:将金针花结及汤汁倒入锅9:放入锅转45分钟炖煮10:开锅11:移至炉火调味并加入苟杞即可12:盛汤', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (42, '山东大煎饼', '面糊，油，肉糜，葱花', '1.煎饼从鏊子上揭下，很柔软，冷却后变脆。放在盖帘上，要立即卷成卷。2.涂上一层山东大豆酱，撒上葱花、青菜等。3.再卷起来。4.从中间切开。小诀窍我想山东人应该是将大葱整棵卷进去的，这样才过瘾。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 2, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (43, '湖南小炒肉', '五花肉，尖椒，蒜片', '1、选较香辣的青尖椒切滚刀片，猪肉带肥前腿肉分肥瘦分别切片，蒜切片。2、锅热较多的油，下蒜片、青椒片、肥肉片炒香，并不断翻炒，直到青椒表面呈微微虎皮状。加入肉片，调盐、老抽、生抽、鸡精，大火快炒出锅。小诀窍肉的时间不易过老或过嫩。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (44, '湘味小炒茄子', '茄子，糖，老醋，蒜，十三香粉，辣椒，泡椒，酱油，盐，味精，猪肉片', '1.将茄子切薄片放在水里略微浸泡。2.剁椒蒜切碎，猪肉切片，辣椒切丁。3.锅内少热油煸炒猪肉至散白，下剁椒蒜煸炒。4.下茄子煸炒，加酱油，盐，味精，糖，老醋，十三香粉继续翻炒。5.盖上锅盖小火焖一会，加辣椒翻炒，水淀粉勾芡即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (45, '湖南蛋', '\"鸡蛋3颗\",\"太白粉或面粉少许\",\"蒜头3瓣\",\"葱1枝\",\"辣椒1~2根\",\"豆豉1大匙\",\"酱油1~2大匙\",\"米酒1大匙\",\"水少许\"', '1:水煮蛋，厨房纸巾沾湿后放入电锅(外锅)，放上鸡蛋，按下去煮，跳起后，冲冷水剥蛋壳2:水煮蛋切片(用切蛋器或缝衣线)、葱、蒜、辣椒切末，用干豆豉的泡米酒备用3:热锅放比平常多一点的油，把蛋片双面沾上薄薄的面粉(或太白粉)，入锅煎至微焦后起锅备用4:同锅爆香蒜末、葱白、辣椒后，加入豆豉爆炒后，加入酱油、米酒、水5:将煎过的蛋片，放入锅略翻炒入味，撒上葱绿，即可起锅', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (46, '湘乡回锅藕', '莲藕1节，芹菜1根，小米椒2只，蒜2瓣，辣椒酱1茶匙，生抽1茶匙，油4大勺', '1.莲藕洗净去皮，切薄片，芹菜洗净斜切切段，小米椒切碎，蒜切片2.汤锅烧水，水沸后放入藕片汆烫3分钟3.捞出沥干水分，撒少许生粉抓匀4.锅中放宽油，烧至6成热，放入藕片炸至表面微焦5.捞出藕片，沥干多余的油6.锅中留底油，再次烧热，放入辣椒酱，炒出红油7.放入藕片，加入生抽，翻炒均匀8.放入小米椒，蒜片和芹菜，继续翻炒两分钟即可', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (47, '剁椒鱼头', '主料：胖头鱼头1个（2斤），湖南特制剁椒，调料：盐2克，味精3.5克，糖1克，色拉油60克，红油10克，姜10克，葱8克', '1、将鱼头洗净切成两半，鱼头背相连，泡红椒剁碎，葱切碎，姜块切末，蒜半个剁细末。2、然后将鱼头放在碗里，然后抹上油。3、在鱼头上撒上剁椒、姜末、盐、豆豉、料酒。4、锅中加水烧沸后，将鱼头连碗一同放入锅中蒸熟（约需10分钟）。5、将蒜茸和葱碎铺在鱼头上，再蒸一分钟。6、从锅中取出碗后，再将炒锅置火上放油烧至十成热，铲起淋在鱼头上即成。小诀窍有时可直接使用从超市买回的剁椒制作此菜品，因成品剁椒中含有较多的盐分，因此，在放盐时应考虑这一因素，以便盐分太重。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (48, '湘菜家常豆腐', '\"老豆腐150g\",\"青椒50g\",\"红萝卜50g\",\"木耳3-4片\",\"姜5g，切片\",\"蒜2瓣\",\"盐1茶匙\",\"糖1/2茶匙\",\"豆瓣酱1汤匙\",\"芡汁\",\"生粉2茶匙\",\"*溶于30mL水中\"', '1:红萝卜切菱形2:青椒切菱形3:木耳撕成小块4:豆腐切成三角形块5:中高火加热适量油，加入豆腐煎至两面呈金黄色，约需时2-3分钟，取出备6:再加热适量油，加入豆瓣酱炒至出红油7:加入姜和蒜继续炒香。倒入木耳，青椒和红萝卜翻炒均匀8:之后倒入豆腐，加入适量盐和糖调味9:之后倒入适量水煮沸，再倒入芡汁收汁10:当汤汁变得浓稠时，起锅即成', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (49, '贵妃牛鞭', '原料：牛鞭400克,黄花菜（又名金针菜）、红枣、枸杞、当归、香附、党参各2克。调料：色拉油200克，食盐5克，味精3克，八角2克，桂皮2克，整干椒3克，葱3克，蕃茄沙司5克，生粉3克，香油2克，辣妹子3克，姜4克，料酒3克。', '1、干黄花菜用温水泡20分钟左右，清洗两到三次，挤干水份备用；2、将牛鞭用凉水泡10分钟，再煮5分钟，捞出后辟开两半，去掉筋膜，放沸水中煮10分钟，捞出后剞一字刀约六七刀（过油受热后自然翻起成鞭花）。姜切小片待用。3、锅上火，下底油100克，烧到七成热，下入八角、桂皮、整干椒、葱、姜炒香，放入牛鞭，加料酒、辣妹子，放适量水烧开，倒入高压锅煮5分钟取出，去掉香料。4、锅烧油100克，下姜片炒香加入番茄沙司略炒，放入牛鞭，放泡好的干黄花菜、红枣、枸杞、当归、香附、党参、盐、100克水小火煨30分钟（放高压锅内则压10分钟即可）煨烂入味，放味精，勾薄芡，淋香油出锅。小诀窍管小伟黄花菜提示您:黄花菜选用晒干的干菜,色暗黄两头有点发黑的黄花菜才是天然无添加的,黄花菜干菜色金黄,外观非常漂亮的是加工过的黄花菜,大家请注意.', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (50, '湘菜版梅菜扣肉', '带皮五花肉500克、梅干菜(宜宾芽菜也行，那就叫咸烧白了，四川风味的）100克、甜酒水（醪糟水）一小碗、酱油1汤匙（15ml）、料酒1茶匙（10ml）、盐适量、料酒1茶匙（5ml）、葱一根。', '1、锅中放入适量的水，放入料酒、葱结烧开，将四方周正的五花肉放入水中（如果太大可一切两块），煮20分钟左右，肉八成熟时捞起沥干水分。2、将少许甜酒抹在冷却后的肉皮上，用手指抹匀，让肉皮均匀地沾到，等甜酒被肉皮吸收后，再抹一层酱油加深颜色。晾干待用。3、炒锅或者平底锅内放入少量的油，将肉皮朝下放入锅中炸至肉皮呈棕红色时捞起（炸的时候因为肉里有水分所以油会噼啪作响，如果怕热油溅到自己，可以用锅盖挡一下，肉皮要煎得棕红微微起泡）。然后将肉块放入煮肉汤中浸泡，这是关键，目的是让煎制的肉皮面起皱。4、待肉凉后肉皮朝上切薄片至2/3处（我切断了，为了好摆盘）。将剩余的酱油、甜酒混合成料汁。将切好的肉片一片片地在料汁中浸一下，肉皮朝下整齐地码在一个大碗内（码碗艺术！我好象自由发挥了一把，明显不落俗套~）。5、将泡洗好的梅干菜（有建议要用油先炒香梅干菜，我给省了，最好别省，别学我偷懒）铺在肉片上面，压实，放入蒸锅内大火蒸一个半小时（中间别忘了添水），吃的时候用一个大盘扣在蒸肉的碗上，翻转过来，将碗移走。6、大火烧热炒锅，将倒出的汤汁放入锅中，加两粒冰糖煮沸熬至浓稠再淋回肉上（这是我加的，不记得湖南做法有这步。如果嫌麻烦，可以省略）。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (51, '干锅羊蹄', '主料：去骨山羊蹄配料：八角、桂皮、草果、白蔻、香叶、干椒、葱、姜、蒜', '1、锅置旺火上，倒入植物油和红油，放入姜块、葱结、干椒、豆瓣酱煸香至呈红色。2、下羊蹄一块煸炒，烹入料酒，加入鲜汤。3、旺火烧开后撇去浮沫，加入盐、味精、鸡精粉调好味，移至小火上煨至羊蹄九成烂。4、挑出香料，装入干锅内，撒上葱段，淋上香油、山胡椒油即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (52, '香辣羊肚丝', '主料：羊肚丝配料：净冬笋水发香菇、大蒜、桂皮、干朝天椒、葱姜蒜、香菜调料：料酒、酱油、盐、香油、湿淀粉、味精', '1、冬笋切成片；香菇去蒂，切块；大蒜切成斜段；葱、姜拍破；香菜洗干净。2、净锅置旺火上，放入猪油烧沸，下入冬笋羊肚丝和香菇煸炒，放入料酒、酱油、盐、桂皮、干朝天椒和鲜汤。3、烧开后装入垫有底的砂钵，用小火煨烂。4、去掉砂钵里的葱、姜、桂皮、干朝天椒，倒入锅内，收浓汤汁，加味精和大蒜，用湿淀粉调稀勾芡，淋上香油，入盘撒上香菜即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (53, '魔都湘味鸡', '鸡腿3个、彩椒少许、鸡蛋1只、淀粉、醋、糖、味精、姜末、蒜末、生抽、料酒、胡椒粉、干辣椒', '1、首先鸡腿拆骨、切块，加少许盐、胡椒粉、料酒、蛋液、腌制一会。2、彩椒切大丁，把蒜末、姜末、葱花、醋、白糖、味精、生抽一起放在一个小碗里调制一下备用。3、腌制好的鸡块用淀粉抓匀，放入180度油温炸之金黄色捞起沥油。4、锅里少许油煸炒彩椒装盘备用。5、再留少许油煸炒干辣椒，然后把刚才调制好的调料倒入锅里，加少许水煮开滚之浓稠状，倒入鸡块彩椒一起翻炒，即可出锅装盘！', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (54, '湘味海参', '冬菇8只泡发切丝，鱿鱼适量切丝，海参一只切丝，各种辣椒切丝，新鲜蒜片', '1，食用油爆锅，加入葱姜，辣椒丝，蒜片翻炒片刻，再依次加入海参翻炒，冬菇丝，鱿鱼丝翻炒。2，加入蚝油，豆豉，生抽适量，大火炒至熟，盛盘，撒些葱花。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (55, '桂来标湖南腊肉炒高丽菜', '\"高山高丽菜四分之一颗\",\"腊肉一小块约六公分正方形\",\"青葱一根\",\"大蒜两粒\",\"干辣椒一根\",\"花椒七~九粒\"', '1、腊肉切成片状，用沸水汆烫过，备用2、起油锅，加入花椒与干辣椒微炸一下再滤掉，只是要添加油香；放入蒜片爆香，再放入腊肉翻炒，要逼出腊肉的油；淋一小匙米酒在锅边，呛个锅。3、放入高丽菜拌炒，炒到高丽菜都软了，尝一下味道若觉不够咸可以加一咪咪盐，最后下葱段再翻炒几下就可以上桌了，', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (56, '湖南麻辣腊肠炊饭', '\"有机糙米２杯\",\"有机红萝卜１条\",\"有机青豆小半碗\",\"橄榄油适量\",', '1:洗米》》（洗米水可以用来浇花！）将红萝卜切滚刀块将青豆洗净将腊肠拿出》》此间店的湖南腊肠很正点，值得一试！2:将红萝卜及青豆放在洗净的糙米上再淋上橄榄油再加入４杯水接着开始煮饭3:在此同时，斜切湖南腊肠为片状4:待米煮至８分熟，水分快要完全被米完全吸收时，将腊肠平铺在饭上待米煮熟，即可享用！', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (57, '湖南风味香菜辣椒牛肉', '\"牛绞肉适量\",\"香菜半把\",\"蒜头五瓣\",\"青辣椒五小根\",\"胡椒粉酌量\",\"姜三小片\",\"孜然粉酌量\",\"酱油一大茶匙\",\"糖1/2小茶匙\",\"米酒一大茶匙\",\"盐1/2小茶匙\",\"鲜味炒手一小茶匙\",\"小红辣椒两小根\",', '1:蒜头、姜切末。青辣椒、红辣椒去籽切末。2:牛绞肉洗干净备用3:香菜切末备用(埂也可以留着比较香)4:起油锅下牛绞肉翻炒，加上米酒跟酱油炒到有肉香捞起备用。5:起油锅下姜末、蒜末、青辣椒、红辣椒拌炒，之后加入牛肉。放一点水，加入糖、盐、胡椒粉、孜然粉调味，最后加入香菜拌炒即可(起锅可以淋一点香油增加香气)', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (58, '湘味烧鱼', '活草鱼1条（1千克左右），新鲜长指青椒4根，豆豉小半勺，蒜瓣5个，老姜5片，盐适量，生抽适量，菜籽油适量', '1、活鱼宰杀洗净，用刀切成3厘米厚的块，用少量盐加2片姜腌制10分钟。2、青椒横刀切碎，蒜瓣用刀拍一下出裂纹。3、锅中放入适量菜籽油，烧到没有泡泡（冒青烟），依次放入鱼块中火煎到两面金黄。4、加生抽和豆豉爆出香味，再加半碗水。5、然后把碎青椒和蒜瓣盖到鱼上面，中火煮10分钟，出锅装盘即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (59, '湘味牛肉', '主料：黄牛后腿肉400克（净料），洋葱末5克。调料：干椒粉15克，孜然粉5克，盐5克，味精5克，辣妹子酱10克，蚝油6克，郫县豆瓣酱5克，美极鲜3克，生抽3克，嫩肉粉0.5克，色拉油300克，红油10克。', '1、黄牛肉切5厘米长、3.5厘米宽、0.3厘米厚的大片，用盐、味精、生抽、嫩肉粉腌渍10分钟入味，待肉质松软时备用。2、锅上小火，下入蚝油、美极鲜、红油对成稠汁。３、净锅置火上，倒入色拉油烧至五成热时，放入牛肉片小火滑油４分钟至七成熟，入漏勺滤净油分。４、锅洗净置火上，下底油烧至五成热，下入洋葱末、干椒粉、孜然粉、豆瓣酱煸香后，入牛肉、辣妹子翻炒颠锅，使之均匀粘上配料，然后出锅装盘，点缀香菜，随对好的汁上桌。小诀窍特点牛肉滑嫩、香气扑鼻。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (60, '湘式剁椒章鱼须', '章鱼须200克，湖南剁椒酱1大匙，豆豉10克，蒜适量，姜适量，香菜适量，孜然适量，芝麻适量，糖适量', '1.把章鱼须放到开水中焯一下，差不多30秒就好啊，时间长了就老了.2.起锅倒油，油热后放入蒜和姜爆香，3.然后放入剁椒酱和豆豉炒出香味，放入糖炒匀.接着放入焯好水的章鱼须，加入孜然和芝麻翻炒均匀加入香菜就做好了!', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (61, '湘式卤汁', '卤包：6粒，花椒2两，甘草1两，桂枝1两，陈皮1两，丁香1两，小茴香1两，香叶1两，辛香料：4支，姜100公克，蒜头15粒，辣椒5支，盐100公克，鸡粉50公克，砂糖100公克，酱油900㏄，米酒120㏄，老抽100㏄，高汤3000㏄', '1.取锅，加入少许油、辛香料爆炒后盛起。2.续于锅中放入八角和花椒炒香后，连同其他卤包材料一起装入卤包袋中绑紧。3.在锅中加入剩余的调味料、作法1、2的食材先以大火煮至滚沸，再以小火慢煮4小时即为湘式卤汁。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (62, '湘味小河虾', '小河虾3两，姜，生抽，白糖，米醋，盐，韭菜一小把，朝天椒', '1.将新鲜的小河虾洗净、擦干备用。2.净锅入宽油，八成油温，将小河虾炸至皮红、酥脆。捞出沥干油分3.锅内留底油，加姜丝爆香，加切成小段的美人椒和炸好的小河虾翻炒均匀，加生抽两大勺、米醋一勺快速翻炒至出香味。4.转小火加白糖两小勺、切成3厘米的韭菜段适量、盐适量，翻炒均匀（3、5秒钟）即可。小诀窍要点1：洗净的小河虾最好用干布或者餐巾纸擦干，以免水分过多使油温降低，也可以缓解溅油的问题。要点2、炸虾不同于普通的滑肉，需要多油、高温，一定要把油温烧得高些再炸。在自己家里做油放得太多比较浪费，所以我都是把虾分成三份，分别炸。这样就不需要特别多的油了。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (63, '湘味蒸腊鸭', '腊鸭半只，蒜末1大勺，豆豉1大勺，辣椒粉1大勺', '1.腊鸭斩块过茶油爆香，使其皮收紧，炸好捞出；2.余油下蒜末，豆豉，辣椒粉小火煸香，加少许水调成汁淋到腊鸭上；3.将腊鸭入高压锅隔水大火上气蒸半小时出锅撒少许鸡精拌匀就ＯＫ了！小诀窍腊鸭本身有盐，无须另外再加，辣椒粉依个人口味调放，蒸的时候一定要加少许水，蒸发才好吃～偷懒的话不下锅，所有材料一起放入碗里直接蒸也很不错，只是香味稍淡点～', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (64, '麻婆豆腐', '原材料：豆腐450克，牛肉末150克，大蒜叶2根，姜茸1汤匙，蒜茸1汤匙，干辣椒4只，葱1条。调料：盐2茶匙，郫县豆瓣酱2汤匙，花椒1/2汤匙，糖1/2汤匙，胡椒粉1/2茶匙，熟花椒粉2茶匙，玉米淀粉2茶匙。', '一、烧开一锅水，放盐2茶匙，放入切成块的豆腐，慢火煮20分钟，轻轻捞起滤水备用，在煮豆腐的时候腾出手来处理香葱，把葱白剁成茸，葱绿切粒；二、锅置炉上，开中火，倒入肉末，用锅铲捣散，煸至出水，如果水太多可滗起，如果水不多则大火收水，盛起备用；三、起锅，放菜约油2汤匙，倒入花椒，中火，煸出香味，把花椒捞起；四、开中火，加豆瓣酱和剪成段的辣椒干，煸出红油，倒入姜茸、蒜茸和葱白茸，爆香；五、倒入豆腐和肉末，放糖1/2汤匙，胡椒粉1/2茶匙，翻均匀；六、勾兑淀粉水，玉米淀粉2茶匙，清水1/3杯；七、将淀粉水均匀地淋入锅里，开大火，加蒜叶，兜匀，烧至淀粉水起大泡，装盘；八、在豆腐上撒上熟花椒粉和葱花，可供享用。小诀窍一、豆腐先用盐水煮过可使豆腐增加韧性和有底味；二、曾经看过网上的说加蒜叶更增香，这次就加了些，果然不错；三、所谓熟花椒粉，将自己研磨过筛的花椒粉炒香晾凉后装瓶，到使用时撒在食物上就可以了。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (65, '水煮肉', '五花肉1000克，白菜半棵，木耳几朵，郫县豆瓣酱50克，辣椒50克，花椒20克，八瓣1个，姜一块，蒜半头，葱半根，胡椒粉10克，全兴大曲酒1勺，骨汤1碗，盐适量', '1、热油爆香郫县豆瓣酱、辣椒、花椒、八瓣、姜蒜，得到香辣红油。取出一些煸香的辣椒花椒备用。2、另取一锅，用刚才1/3的香辣红油炒下白菜。3、几分钟后，倒入大碗里。4、用2/3的香辣红油，加入骨汤、木耳煮沸。5、加入肉片。6、沸腾后，淋白酒，加胡椒粉、盐调味。7、全部倒入垫了白菜底的盆中，撒些葱末。最后起锅烧油到冒烟。把第一次煸香的辣椒花椒洒在肉片上。把烧热的油，迅速倒在盆中，满钵飘香的水煮肉片就做好了。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (66, '鱼香肉丝', '猪里脊肉300克，绿尖椒1根，胡萝卜1/4根，冬笋1/2根，黑木耳6朵，配料：腌肉调料（生抽5ml，料酒5m，水淀粉20ml），鱼香汁（生抽5ml，醋15ml，白糖45克，盐1克，水淀粉20ml），色拉油80ml，葱，姜，蒜末适量，四川泡辣椒4-5根', '1、猪里脊肉切细丝，加腌肉调料腌制十几分钟；2、绿尖椒、胡萝卜、冬笋分别切细丝，黑木耳泡软洗净切细丝备用；3、调好鱼香汁备用，葱、姜、蒜切末备用，泡辣椒切末备用；4、锅中放足量油，油六七成热时放入肉丝大火快速滑散至变白，盛出备用；5、锅中放少许油，放入葱、姜、蒜末炒香，放入泡辣辣末炒出红油；6、放入胡萝卜、冬笋、木耳翻炒2分钟，放入尖椒翻炒均匀；7、放入炒好的肉丝迅速翻炒均匀；8、倒入鱼香汁快速翻炒均匀即可。小诀窍1、肉丝的腌制和炒制：肉丝要提前腌制一下，大火快速滑炒，以保证肉丝的滑嫩；2、配菜的选择：鱼香肉丝通常用的配菜有冬笋、黑木耳、绿青椒（或尖椒）、胡萝卜，一般来说冬笋是必不可少的，其他几项为可选；3、泡辣椒的选择：做鱼香肉丝的辣椒用的是四川的泡辣椒，如果实在买不到，用剁辣椒代替也可。泡辣椒和剁椒的腌制方法应该比较相似，但还是有区别，而且辣椒的选择也不同。从色泽上看，泡辣椒可以炒出红油，菜色有点发红，剁辣椒则不会上色，味道也有一点差异。我用剁辣椒也炒过鱼香肉丝，味道差不多，但还是差一点儿哈~只有真正的四川泡辣椒的味道才是最地道的；4、鱼香汁的调制：鱼香肉丝的味道对不对，除了泡辣椒的选择就是鱼香汁的调制了。一般糖和醋的比例为3：1即可，可依个人口味稍做增减哈~', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (67, '回锅肉', '青椒、五花肉、土豆、花椒、姜片、蒜头、干辣椒、生抽、老抽、鸡精、糖', '1、青椒洗净切片，土豆洗净去皮切片，五花肉切片。2、首先起油锅，下花椒、姜片、蒜头煸炒出香味。3、下五花肉煸炒。火不要太大，以免糊了。把五花肉的油都逼出来，捞起备用。4、下土豆片翻炒。5、炒的差不多时，放青椒、五花肉、干辣椒一起翻炒。6、加生抽、少许老抽上色，稍微加一点水、鸡精、糖翻炒即可出锅。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (68, '鱼香茄子~~川菜的经典料理', '\"茄子1-2条\",\"猪绞肉适量\",\"大蒜5-6颗\",\"姜丝少许\",\"葱末少许\",\"酱油一匙\",\"糖少许\",\"盐少许\",\"白胡椒粉适量\"', '1:两大匙油热，茄子切段用半炸半炒方式保留茄子颜色跟软嫩起锅备用2:重新热少许油，下猪绞肉，姜丝，大蒜，酱油，糖，盐，炒熟后加入茄子，加胡椒粉，葱花，拌炒一下就可以起锅', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (69, '川菜回锅肉', '\"主　料：带皮五花肉500g\",\"辅　料：青椒2个（150g）\",\"蒜苗2根（80g）\",\"葱半棵（40g）\",\"姜1块（20g）\",\"八角3朵（4g）\",\"肉桂3g\",\"调味料：绍兴花雕酒3大匙（45mL）\",\"酱油2小匙（10mL）\",\"辣豆瓣酱1大匙（30g）\",\"甜面酱1大匙（30g）\",\"食盐1/2小匙（3g）\",\"鸡粉1/2小匙（2g）\",', '1:青椒去除蒂和籽，切成片；蒜苗洗净，斜著切成3～4cm长的段；葱洗净，切成约4cm长的段；姜去皮，切成片；2:汤锅加水，加入2大匙花雕酒（可用红标米酒替代）、姜片、葱段和八角大火烧开，放入五花肉转小火煮30分钟至七成熟；3:五花肉捞出后用冷水清洗、沥乾，冷却后切成约5cm长、3cm宽、3mm厚的片；4:炒锅加少许沙拉油烧至五成热，放入五花肉快速煸炒；5:肥肉出油时加入辣豆瓣酱和甜面酱，炒出香味并上色；（本菜为四川风味，原本应该用四川的郫县豆瓣，这里换成台湾的辣豆瓣酱，如果不爱吃辣可以选用不辣的豆瓣酱）6:再放入青椒和蒜苗快速炒匀，加入1大匙花雕酒、酱油、食盐和鸡粉调味；7:待青椒和蒜苗炒熟即可出锅。8:上桌。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (70, '川菜食谱 - 麻辣土豆丝', '\"2个马铃薯（或1个大）\",\"适量葱\",\"适量蒜茸\",\"几片红椒调味\",\"1-2茶匙辣酱(建议使用“老干妈“)\",\"适量盐\"', '1:马铃薯，去皮，切丝2:在水中浸30分钟3:用蒜茸把土豆炒香4:添加红椒丝5:加入辣酱6:添加葱7:川菜食谱-麻辣土豆丝8:川菜食谱-麻辣土豆丝', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (71, '四川菜炒马铃薯', '\"四川菜一粒\",\"马铃薯大粒的一粒\",\"瘦肉一小碗\",\"蒜蓉少许\",\"糖少许\",\"胡椒粉少许\"', '1:准备食材。把四川菜，瘦肉及马铃薯都切成条状。2:锅热后，下油炒香蒜蓉。加入瘦肉炒至半熟。3:加入马铃薯，炒一分钟后，放入四川菜，继续炒。4:加水慢火煮软马铃薯。5:加糖，胡椒粉调味。等水干了，马铃薯软了便可以了。如果喜欢，可以加入老抽。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (72, '蚂蚁上树（辣炒冬粉）川菜', '\"青葱一把\",\"姜一块\",\"蒜67粒\",\"香菜叶起锅摆盘\",\"香菜梗切碎适量\",\"猪绞肉200公克\",\"辣豆瓣酱12大匙\",\"冬粉4把泡冷水\",\"酱油1大匙\",\"米酒12大匙\",\"鸡粉适量\",\"红油适量\",\"芝麻油适量\",\"高汤（清水也可）250C.C.\",', '1:冬粉泡冷水到微软,剪几段,沥干水份备用！2:所有辛香料切成细末.葱绿切末和香菜根末放一起.3:爆香绞肉到金黄,下酱油略炒,起锅备用！4:爆香所有辛香料到香味四溢.下辣豆瓣酱爆炒！再下步骤3.加高汤（或水）煮至滚后,下冬粉拌炒,下一半葱绿、香菜根,即可起锅！5:起锅后洒上剩下的葱绿香菜根,淋上烧热的红油,即完成！', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (73, '四川干煎鸡 (改良香港云阳川菜餐厅作法) @苏发福日记', '\"鸡腿(或鸡腿上部（鸡上脾))2大只（或鸡上脾5~6块)\",\"干辣椒1碗\",\"辣椒粉适量(视接受辣的程度)\",\"小辣椒切碎2~3根\",\"花椒1大匙\",\"花椒粉2小匙\",\"盐适量\",\"糖适量\",\"太白粉2大匙\",\"蒜片适量\",\"葱段3~4根\"', '1:醃鸡：退冰的鸡腿去骨，连皮切小块（一口吃的大小），先以塩、辣椒粉、糖及花椒粉1小匙抓醃，再入2大匙太白粉抓醃，放置约半小时。2:炸鸡（或半煎炸）：起油锅，将油热到180度左右，下鸡块炸至金黄捞起（锅小可以分次炸）。3:2次炸鸡:待鸡全捞起，将油上的浮末及粉屑捞起，油再以大火加热至200度（比第一次的油温更高即可）后，将炸鸡放入，炸约30秒即可捞起。用厨房纸巾将鸡上油份吸掉。4:炒花椒：另取一锅（我是以同个锅子，掉倒部分油），放入1匙油，以小火慢慢爆香花椒约5～10分钟，千万不要让花椒变焦黑。之后将花椒沥油捞起。5:炒干辣椒：同4的锅子，以中大火爆炒蒜片、干辣椒、辣椒末。炒至干辣椒胀起有香味后，加入葱段大火爆炒。6:最后：加入鸡丁、1小匙花椒粉、辣椒粉，以大火继续爆炒约5分钟，起锅前试味，可加塩、辣椒粉调味咸度及辣度。完成。7:大火炒的连蒜片都好酥脆～', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (74, '经典川菜【麻婆豆腐】', '嫩豆腐350g、牛肉100g、郫县豆瓣酱15g、豆豉5g、青蒜1棵、姜1块、大蒜2瓣、辣椒粉5g、花椒粉1g、料酒15ml、生抽10ml、白糖3g、辣椒油15ml、水淀粉适量、油适量、盐少许', '1.牛肉洗净剁成细末，姜切末，大蒜切碎，青蒜洗净切碎，豆瓣酱和豆豉分别剁细；2.豆腐洗净，切成2厘米见方的块，放入加了少许盐的沸水锅中，中小火焯烫1分钟，捞出沥水；3.锅中放入油烧热，放入牛肉末小火煸炒，待水分煸干牛肉香酥出油后，放入郫县豆瓣酱、豆豉和辣椒粉炒出红油，放入姜、蒜末炒出香味，加入小半碗水、放入料酒、生抽、白糖和盐烧开；4.放入豆腐小火煮2分钟，用水淀粉勾芡，再继续用小火煮2分钟，撒上青蒜，再次用水淀粉勾芡即可出锅，最后撒上花椒粉，淋上辣椒油即可。小诀窍**新鲜的嫩豆腐很容易出水，在煮的时候最好进行两次勾芡。**豆腐焯水时加少许盐不但可以去除豆腥味，还可以保持豆腐形态的完整不易碎裂。**没有牛肉末可以用猪肉末代替，有时候我不想自己剁牛肉馅，就直接买猪肉馅来做麻婆豆腐，味道一样很好的。**可以根据喜好选择用内酯豆腐，但不宜选用老豆腐。**最后的辣椒油可以不放，因为有辣椒粉已经是蛮辣了的。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (75, '川菜红油', '菜子油50kg，二荆条辣椒面7.5kg，朝天椒辣椒面2.5kg，大葱节2.5kg，洋葱块1.5kg，香菜2kg，老姜拍破1.5kg，熟芝麻0.5kg香料：八角、桂皮、香叶、草果、白蔻、小茴、丁香、砂仁适量', '1、将菜子油烧至八成热时离火，投入大葱、洋葱、老姜、香菜炸干后捞出。2、待油温降到五六成热时，下二荆条辣椒面7.5kg、朝天椒辣椒面2.5kg及香料搅拌均匀后，最后加入熟芝麻即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (76, '西芹炒川味腊肠', '\"西芹2根\",\"川味腊肠80克\",\"盐适量\",\"姜1小块\",\"大蒜1小瓣\",\"食用油少许\",', '1:准备用料：西芹2根，川味腊肠80克，盐适量，姜1小块，大蒜1小瓣，食用油少许。2:将西芹表面清洗干净，从端头将皮肉里的粗筋拉出，一根根撕掉。3:再斜切成片，备用。4:腊肠事先煮熟，切成斜片。5:生姜洗净表面泥沙，大蒜去皮，分别切成片。6:炒锅置火上，倒入少许食用油，中火烧热。7:放入姜蒜片，炒香，8:再将切好的腊肠放入锅中，煸香出油。9:把煸炒出油的腊肠拨到锅边，放入西芹片，快速翻炒至断生，10:在西芹中加盐，翻炒均匀。11:再将炒好的腊肠拨回锅中，与西芹一起翻炒均匀。12:熄火，出锅，装盘。13:也许，用广味香肠来炒西芹，才会保留西芹那青青白白的颜色。14:红红的辣椒，随着腊肠渗出的油脂，把西芹也染成红油色。不过，微带着些许辣味的西芹也是别有一番风味。小诀窍西芹与腊肠的用量可以根据自己喜好适量食量随意增减。腊肠煸炒出油后吃起来更香。川味腊肠可以用各种腊肠代替。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (77, '川味牛肉面', '\"牛腱心2斤\",\"牛腩1/2斤\",\"蕃茄2个\",\"红萝卜1条\",\"白萝卜1条\",\"洋葱1个\",\"老姜8片\",\"卤包1个\",\"拉面2斤\",\"小白菜1/2斤\"', '1:食材集合-牛腱,牛腩先不切,整条先川烫下去熬煮,老姜切薄片,洋葱切片状,小白菜切段,蕃茄1对8切开,葱切珠状备用2:用汤锅装适当水,放卤包先煮.3:牛腱整条先川烫用清水漂洗去血水,牛腩也先川烫后放入汤锅中盖锅续煮.4:另锅用香油爆老姜片,爆至姜片卷曲出香味,5:再放入洋葱片炒软,加入辣豆瓣酱,酱油膏,冰糖,味精及水,煮滚至洋葱软烂甜味释出,捞起食材,6:汤汁过滤放入汤锅一起煮开,7:这时可加入红白萝卜条(一切四),小火焖煮约1.5小时后8:将牛腱牛腩红白萝卜拿出切片及切块备用.9:牛腱牛腩切片10:汤锅再放入番茄煮一下,最后调味加盐即可.面条入滚水煮５分钟，捞于大碗中，加入牛肉汤、牛肉块、小白菜、葱花等即可享用.', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (78, '川味凉粉', '\"绿豆粉皮（干燥的）1包\",\"小黄瓜1条\",\"花生适量\",\"蒜适量\",\"辣椒适量\",\"花椒（要做花椒油）适量\",\"调味料如下\",\"酱油1大匙\",\"蠔油1小匙\",\"黑醋1小匙\",\"糖1小匙\",\"花椒油1小匙\",\"香油1大匙\",\"辣椒油1小匙\",', '1:我这次有买花椒回来，自己做花椒油⋯冷锅冷油，放入花椒炒出麻香味即可，将花椒油沥出备用！火不要太大，花椒炒黑容易变苦苦的！2:花椒油⋯只取油的部份，炒过的花椒不用！平常，可先做起来放冰箱，要用的时候就很方便！3:我买的是这种凉粉皮⋯是用绿豆淀粉做的，用法很简单，这本来就是熟的⋯食用前泡在食用水内软化，软化后再切丝！4:大概泡个15～20分左右就软化了！5:将花生放入ㄧ袋子中，敲成花生碎⋯备用！6:蒜和辣椒切末放入酱料调好备用、小黄瓜切丝舖在盘上，软化的凉粉皮切丝备用⋯花生碎备用！我分成俩份，辣味版和小朋友吃的清爽版～先将备好的凉粉放在冰箱冷藏⋯7:要吃的时候，再将酱料淋在凉粉上，再洒些花生碎⋯冰冰凉凉、酸酸辣辣的川味河粉轻松上桌啦！?8:真的好适合夏天，吃起来很够味又清爽⋯推荐给你们', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (79, '经典川菜魔芋烧排骨', '排骨500克，魔芋500克，干辣椒10颗，八角5粒，火锅底料半袋，豆瓣酱适量，料酒，糖，醋，老抽适量，葱段，姜片，蒜片适量', '1、排骨小段，过开水汆一下，捞起。2、魔芋切条状，开水加盐，煮几分钟入味，捞起。3、小火准备热锅，将干辣椒调料下锅炒出辣味，下油适量。4、将葱姜蒜下油锅炒出香味，再加入豆瓣酱和火锅底料，直至油变成红色。5、下排骨大火炒，同时加入少量料酒、醋、糖、酱油。让排骨尽量上色、出油。6、加入开水，以没过排骨为适宜。大火炖。7、约二十分钟后，加入魔芋，共炖。开小火。8、排骨烂熟后起锅。小诀窍魔芋提前煮入盐味。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (80, '川菜酸菜鱼', '黑鱼肉，酸菜，葱姜，红米椒，花椒', '1、鱼肉片成较薄的鱼片，用盐抓洗几遍后冲洗干净并充分沥干，加少许盐黑胡椒粉，料酒抓到发粘腌制15分钟以上。2、酸菜挤干汤汁切成丝，姜切片，葱切末，米椒切小段。酸菜的汤汁不要倒掉，后面加到汤里，汤的味道更好。3、油锅烧热，倒入酸菜煸香后盛出备用。煸炒过的酸菜更脆爽。4、锅内继续倒入油，姜片爆香，再倒入鱼头、鱼尾、鱼骨这些翻炒到完全变色后调入适量料酒。5、锅内加入适量的水煮开，大火煮至汤汁发白。大火才能把汤煮白。6、倒入酸菜和酸菜的汤汁煮10分钟左右至味道融合，并加适量盐和胡椒粉调味。7、把酸菜和鱼骨先盛到碗里，锅里剩下汤汁煮开后下入腌好的鱼片，迅速划散，锅内再次煮开后马上关火，连汤一起盛入碗内。鱼片下锅之前倒些色拉油抓匀，这样可以防止鱼片粘在一起，也能锁住水份，保证鱼片鲜嫩，锅里只留汤汁，这样鱼片更容易熟一些，不至于煮太久而口感变老。8、酸菜鱼的表面撒上葱花，米椒和花椒，另起一口干净的锅，加适量油烧热后倒在酸菜鱼上即可。这步不要省，浇上热油后，酸菜鱼的鲜香麻辣都给激发出来了。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (81, '火爆川菜之三椒煸鸡', '【原材料】：鸡腿2个、干辣椒10个左右、小米辣8个、泡野山椒随意、蒜5-6瓣。【调味料】：A料：鸡蛋半个、1大勺鲜味酱油、盐1小勺、糖1小勺、生粉1-2大勺。B料：植物油300ML（实耗少量）。C料：植物油1大勺、豉油鸡汁1大勺、生抽1大勺。', '1：将鸡腿去骨后，用刀背稍剁一下把筋膜剁断。2：切成大丁后，加入A料中的蛋液、酱油、盐和糖拌匀。3：再加入生粉抓匀，腌制10分钟。4：锅入B料植物油，加热至120度炸鸡丁，小火炸制以免将肉炸老了。注意用筷子搅散，以免粘连，炸成淡淡的金黄色捞出待用。5：炸的过程中将干辣椒、小米辣切段，蒜切粒。6：锅入C料油，炒香干椒段和蒜粒。7：再放入其它两种辣椒炒匀。8：加入鸡丁中大火翻炒。9：最后加入其它C料炒匀即可。小诀窍1、鸡肉先行入味腌制再炸，注意炸的时间油温不要高，时间也不要太长，不要将肉炸硬炸老了。2、辣椒的辣度可以依自己能承受的能力放入，量可以增减.3、没有豉油鸡汁就用酱油代替就可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (82, '人气川菜酸菜鱼', '黑鱼肉，酸菜，葱姜，红米椒，花椒。（黑鱼肉是菜场现杀后，让菜场的人代为处理成整块的没有大刺的肉，这样自己回家片鱼片就容易多了，切下的鱼头和尾等也不要丢弃。虽然不能吃辣但花椒还是不能省的，可以说花椒是酸菜鱼的灵魂。）', '1.鱼肉片成较薄的鱼片，用盐抓洗几遍后冲洗干净并充分沥干，加少许盐、黑胡椒粉、料酒抓到发粘腌制15分钟以上。2.酸菜挤干汤汁切成丝，姜切片，葱切末，米椒切小段。（酸菜的汤汁不要倒掉，后面加到汤里，汤的味道更好。）3.油锅烧热，倒入酸菜煸香后盛出备用。（煸炒过的酸菜更脆爽）4.锅内继续倒入油，姜片爆香，再倒入鱼头，鱼尾，鱼骨这些翻炒到完全变色后调入适量料酒。5.锅内加入适量的水煮开，大火煮至汤汁发白。（大火才能把汤煮白）6.倒入酸菜和酸菜的汤汁煮10分钟左右至味道融合，并加适量盐和胡椒粉调味。7.把酸菜和鱼骨先盛到碗里，锅里剩下汤汁煮开后下入腌好的鱼片，迅速划散，锅内再次煮开后马上关火，连汤一起盛入碗内。（鱼片下锅之前倒些色拉油抓匀，这样可以防止鱼片粘在一起，也能锁住水份，保证鱼片鲜嫩，锅里只留汤汁，这样鱼片更容易熟一些，不至于煮太久而口感变老）8.酸菜鱼的表面撒上葱花，米椒和花椒，另起一口干净的锅，加适量油烧热后倒在酸菜鱼上即可。（这步不要省，浇上热油后，酸菜鱼的鲜香麻辣都给激发出来了。）', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (83, '川菜麻婆豆腐', '嫩豆腐300克，牛肉末100克，花生油40克，豆瓣酱40克，花椒面2克，豆豉12克，酱油12克，料酒15克，精盐2．5克，味精2克，水淀粉25克，葱、姜、蒜各25克', '1、将豆腐切成1．5厘米见方的块，放人温水锅内稍煮，捞出沥水，豆瓣酱剁细，葱姜蒜切末。2、将炒锅置火上，放油烧热，下牛肉末炒散。3、待水分将干时，下豆瓣酱、豆豉、姜蒜米。4、炒出香味后，加料酒、酱油、水（和豆腐一样多为宜）。5、然后放人豆腐、精盐、味精，烧开转小火。6、待豆腐烧透，用水淀粉勾芡，撒上葱花、花椒，盛入盘内即成。7、起锅撒上花椒面，也可以适量加上酱油。麻婆豆腐就做成功啦！大家试试吧！', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (84, '川菜回锅肉', '肉，泡姜，泡海椒，豆瓣，甜酱，味精，盐，蒜苗', '1.先让大家看看主要的原料。2.爆肉的一个要领，要置锅，就是把锅烧热，越热越好，主要是为了不让肉在爆的过程中贴锅。3.爆肉。在爆之前可以加点色拉油进去，我今天买的肉有点偏瘦，没得好多油的。加点油更容易爆出油来.4.肉爆好后，起锅，锅内留油。改小火煸炒泡姜、泡海椒、豆瓣。用小火的目的是为了不让佐料由于火大炒胡，让他的香味与味道都出来就行了。5.佐料炒好后，肉回锅。回锅肉嘛，当然要多回几次锅了。这时再加甜酱，上色，当然加甜酱也是提味的一个关键，跟加糖是一个道理。怎么样，这时有颜色了。6.加味精少许。这时肉基本已经炒好了，如果大家觉得差点味道还可以再加点盐。7.放入蒜苗，再加火小炒一下。注意，不要把蒜苗炒死了，炒生点更香！', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 4, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (85, '豉椒蒸排骨', '猪肋排骨，豆豉少许，生姜，干红椒，葱，生抽，料酒，糖，淀粉', '1.豆豉过一下水洗去表面盐分，用刀剁碎．生姜切成末，干红椒切短，葱切葱花．2.排骨洗净控干水后，加碎豆豉／姜末／生抽／糖／料酒／淀粉适量，拌匀后．静置腌制至少两小时（我有时候晚上准备次日的就腌制过夜，放冰箱加盖即可）。3.蒸笼水滚后排骨连容器入屉．大火蒸20分钟后，洒上干红椒继续蒸10分钟关火．（如果要辣一些就把辣椒混合在腌料中）。4.出锅洒上葱花即可．肉质鲜嫩，豉香诱人。小诀窍这道菜稍微甜口些会更鲜美．', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (86, '粤式肠粉', '材料：粘米粉，生粉，虾仁，牛肉，义烧，葱，油，不粘底小煎锅，汤勺.米浆份量：粘米粉1碗，生粉2/5碗，水4碗，油1/8碗，味精，盐各适量拌均置冰箱四小时以上.注意：因为每个牌子出產的粘米粉与生粉质地都不相冈，试做时自己掂着慢慢的加多或減少一些粉.提示：烹倒时肠粉太软太黏不成形那是水太多.肠粉破裂，试慢慢加多一点生粉.肠粉生天花脸要慢慢多加一点生粉.倒肠粉时开头那5个一定不能尽意，但之后煎锅入油后定会更好，別泄气.', '酱油制法：老抽3匙，生抽1匙，蚝油1/3匙，水2匙，油1/2匙，盐，糖各少许.做法：虾仁洗净用一点生粉与油醃3小时备用，牛肉打碎后放一点泡打粉，蛋清，生粉，油，葱花，味精，盐各适量放在盘子里压扁醃3小时(详细牛肉醃制法可在我帖子里找)，大火水滚后隔水蒸虾仁与牛肉大约5分钟取出备用(用煎锅做肠粉，一些馅要先蒸熟才行)，义烧切小片备用.大火热煎锅，放4匙油让油大热后倒出油再开中小火热原来的煎锅大约2-3分钟再转开大火热煎锅(这个热油开头只用一次以后倒的肠粉都全免油了，这热锅法是使煎锅入油，倒肠粉时热气会平均快熟不会老)热锅后，*一手提起煎锅，一手扚起4/5之汤勺的米漿倒在煎锅上，慢慢的转动煎锅让米浆完会分佈均匀，回放煎锅到火爐上，蓋上蓋大约20-30秒，打开蓋再等半分钟(看濁白色的肠粉变成透明，肠粉的週边己经割离锅边后)，*快手反倒整个煎锅轻轻扣在砧板上(这个比较难，要快力道要恰好，多练习几次吧!)，整片肠粉就会脱锅而出，先褶3/1边后放馅，再褶3/1边蓋在馅上，肠粉就完成，再热煎锅，再扚起4/5之汤勺的米漿再倒在煎锅上，继续烹肠粉….烹好的肠粉用刀切去头尾，摆盘再淋上酱油，即可开吃.', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (87, '广东油鸡', '鸡腿2只，水1/2杯，广东油鸡淋酱13杯', '(1)将鸡腿放入开水中汆烫一下去血水，然后沥干备用。(2)将广东油鸡淋酱放入锅中煮开，然后将鸡腿放入，加1/2杯水，盖上锅盖煮3分钟即可熄火。让鸡腿再浸泡25分钟，即可取出放凉。(3)香油涂在放凉的鸡腿上，然后切块排盘，再淋上少许卤汁即可上桌。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (88, '豉汁蒸凤爪', '凤爪1斤，姜片，花椒，葱，调料Ａ：泡红椒，姜丝，葱头，豆豉，调料Ｂ：1勺豆瓣酱，姜蒜泥，1勺芝麻油，1勺醪糟，4勺蒸鱼酱油，味精，白糖，花椒粉适量', '1）剪掉凤爪指甲2）清洗干净，用很少的盐和2勺米酒拌开3）锅里放凉水，加姜片，花椒，葱煮开，然后加入凤爪煮，大概１０分钟左右，鸡爪至少要半熟，不然后面不容易蒸烂。4）煮了的凤爪捞起来晾干水份，并切成２半5）锅里放油，用中火炸凤爪，炸至表皮变脆，很粘的感觉.（这时的凤爪以７，８分熟为宜）6）炸好凤爪后，锅里留少许油，将豆豉加进去炒香，然后加入调料Ａ翻炒几下即可。7）将凤爪和调料B混合，在碗里铺好，然后将炒好的调料A洒在上面。8）然后上蒸笼蒸。如果前面凤爪已经有７，８分熟的话，用大火蒸１０来分钟就可以了。如果煮得不够，就需要用小点的火慢慢蒸久一点到酥烂为止9）再将蒸鸡爪的豆豉汁淋上一些，洒上点葱花', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (89, '滑蛋虾仁', '海虾250g、鸡蛋3个、小葱2棵、鱼籽1茶匙（没有可不放）、料酒5ml、干淀粉5g、水淀粉30g、白胡椒粉少许、盐少许、油20ml', '1.海虾去头去壳，用牙签将虾线剔除，放入碗中，用料酒、干淀粉5g、胡椒粉和少许盐腌制片刻；2.小葱洗净切碎，鸡蛋打入碗中、加入葱花、水淀粉和盐搅散均匀；3.炒锅放入油，用大火烧热，放入虾仁快速翻炒至虾身弯曲变红；4.倒入鸡蛋液，转中小火，用锅铲推动蛋液，炒至蛋液约8成凝固的状态即可出锅；5.装盘后点缀上适量鱼籽即可。小诀窍**如果觉得自己处理虾仁比较麻烦，可以购买现成的冷冻虾仁代替。**将虾仁放入冰箱冷冻三十分钟去壳更轻松。**虾仁用淀粉抓一下在炒的时候可以锁住水分口感会更脆嫩。**鸡蛋液倒入锅中要用中小火翻炒，在蛋液大概凝固就可以关火了，利用锅底的余温再炒几下。如果不习惯吃口感太嫩的鸡蛋或是担心食用卫生问题，可以把鸡蛋炒全熟了吃就放心些，不过样就是炒蛋而不是滑蛋了哦。**炒滑蛋时在蛋液中加入少量水淀粉会让鸡蛋更滑嫩。**做这道菜最好使用不粘锅，可以少用点油更健康。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (90, '经典粤菜嗜嗜滑鸡煲', '材料：嫩子鸡1/2只（500克）、干葱（红葱头）150克、大蒜8瓣、生姜8片、青红椒各1个、豆豉5克腌料：盐1/4小匙，料酒1大匙，蛋清1/4个，玉米淀粉1大匙调味料：海天海鲜酱1又1/2大匙，蚝油1大匙，清水2大匙，砂糖1/2小匙，黑胡椒1/4小匙', '1鸡斩小块，干葱去皮，生姜切片，大蒜去皮拍碎，青红椒切菱形块。2依次把盐，料酒，玉米淀粉加入鸡块中拌匀，最后加入少许蛋清拌匀。3豆豉剁碎4将调味料放入碗内调匀。5锅内热油，放入鸡块滑炒至变色盛出备用。6豆豉放入锅内煸香，再倒入所有调味料烧至起泡。7加入炒好的鸡块，翻炒至均匀的裹上酱汁。8砂锅内加1/2大匙油烧热，放入姜片、大蒜、青红椒、干葱炒出香味。9倒入炒好的鸡块。10盖上砂锅盖，沿锅边淋少许白酒，烧2分钟即可上菜。小诀窍1.此菜选鸡最好选嫩的子鸡，而且炒的时间不易过长，鸡块转成白色即可。因为还要轻过砂锅的二次加热，不用怕不熟。2.此菜不需要再额外加老抽了，因为海鲜酱可以帮助上色，否则就上色过深了。3.糖不用加的太多，一丁点就行了，因为海鲜酱本身就有甜味的，最好调好那碗酱时试吃一下。4.红葱头的香气很浓郁是做这道菜的关键，北方人也叫干葱，如果买不到就用紫皮小洋葱代替吧。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (91, '豉椒蒸排骨', '猪小排，豆豉1小匙，大蒜3粒，红辣椒1条，葱花少许，太白粉匙半，米酒1匙，盐，糖与味精少许，麻油半匙', '1、猪小排洗净切小块，豆豉泡热水再碾碎，大蒜垛成茸，红辣椒切钭片。2、猪小排放两匙水用手微抓(让排骨吸收水份会更嫩与滑)，放豆豉、蒜茸、盐、糖与味精调味后，加米酒，再用手拌勺，再下生粉抓均，最后放进葱花、辣椒与麻油拌匀后，倒入蒸盘放进冷藏四小时备用。3、大火烧锅热水，放入蒸盘隔水蒸十五分钟即可出菜。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:53', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (92, '粤菜咸鱼茄瓜煲', '【材料】：茄子400克(2条）马交咸鱼60克（一小块）五花猪肉80克大蒜2瓣生姜10克香葱末5克【调味料】：A：玉米淀粉2大匙（裹茄子用）植物油1碗（实耗1/3碗）清高汤1碗（200ml)B：生抽1大匙、老抽1/4小匙、陈醋1大匙、砂糖1又1/2小匙、鸡精1/4小匙', '1.马交咸鱼先用温水浸泡30分钟，取出剔去大骨，切成小块。茄子切成细长段，五花肉切丁，大蒜、生姜剁成碎，香葱切成末，分开葱白及葱青部份。(图1)2.将茄条用玉米淀粉粘裹起来，尽量让茄白部分都粘到粉。（图2）3.锅内倒入1碗油，中火热至170度，放入茄条炸至表面微黄色，茄子内部变软,（图3）炸好的茄子沥干油备用。（图4）4.将调味料B在碗内调匀备用，炒锅内倒1小匙油，放入姜末、蒜末、葱白碎炒至出香味。（图5）5.放入猪肉丁，小火煸炒至出油脂，（图6）放入咸鱼丁炒出香味，（图7）加入炸好的茄条。（图8）6.加入高汤1碗后，再加入事先调好的调味B，（图9）中火煮开后，转小火开盖焖煮至汤汁变浓稠即可。（图10）7.再将做好的菜连酱汁一起倒入砂锅内，加盖用中火烧开,表面洒上葱花即可。小诀窍1.马交咸鱼是广东地区的特产，肉多剌少的一种咸鱼，如果不先用温水浸泡去盐份，煮出来的茄子会很咸。切鱼块时要先把里面的鱼剌切出来，以免吃菜的时侯被剌到。要注意份量，两条茄子只要配2指宽的一块咸鱼份量就够了。2.这里我只用少量的油来炸茄子，因油量少，炸的时侯要把锅子顷斜到一边，分三次放入茄条油炸，以油量没过茄条为准。因外部有粘粉的原因，茄子表面会显的硬，判断茄子内部是否炸软了，要用筷子轻轻压来感觉。3.这道菜的糖要加多一些，以综合咸鱼的味道。高汤可以为菜肴增加鲜味，如果没有，也可以用清水代替。4.因炸茄子里已经在表面沾了玉米淀粉，所以煮制时会自然浓稠，不需要再加水淀粉勾芡了。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (93, '粤菜经典之白切贵妃鸡.', '鸡，葱姜，洋葱，元贝，火腿圈，荸荠，红萝卜，鸡汤，果皮', '1.鸡清洗干净之后，沥干水分，用盐涂鸡身内外，腌制一二个小时以上，鸡壳内放入葱段，红葱头，姜片2.制作浸贵妃鸡水汤汁材料：元贝，火腿圈，荸荠，红萝卜，鸡汤，果皮，姜片，材料放在锅水里煮至沸之后关慢火煮约二小时，让材料充分出味3.煮一锅沸水，把腌制过的鸡去除料头之后，用沸水烫鸡身，鸡内壳要充分浸入沸水里.提起鸡身流出鸡内壳水，重复以上动作三次.这样既可去除异味又可初步段生.4.浸鸡汤水重新加热，放入整鸡，鸡内壳一定要让汤水充分浸入，汤水要盖过整鸡为佳.大火重新煮沸后马上关火，盖上锅盖，焖至13-20分钟，视鸡身的大小或者新鲜鸡冷冻鸡来决定浸熟时间.5.拿出整鸡，放在盘里用黄酒跟原汤水淋上鸡身，之后均匀涂上香油，放凉待斩件6.鲜美的白切鸡就完成了，当然七分鸡味，三分酱味，你可以选用不同的酱料沾酱.嫩滑的白切鸡的最高境介就是，骨中带血，鸡肉鲜嫩.因为鸡肉的蛋白质的特殊性，过熟的鸡肉会\"鞋\".但是现在又有XX病毒，唉烦', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (94, '粤菜----胡椒浸生蚝', '生蚝，葱，姜，红辣椒，香菇，上汤，料酒，生粉，胡椒，鸡精，香油，鱼露，色拉油', '1.生蚝洗净去肠，入沸水中汆水2.葱、姜、红辣椒洗净，切段，香菇水发后，洗净，切段3.胡椒洗净，拍碎4.将上汤、胡椒碎、生粉、鸡精、香油、鱼露兑成汁5.烧锅放油，烧至五成热，放生蚝过油，盛出6.烧锅放油，放葱、姜、红辣椒、香菇翻烧至香，放生蚝，加料酒、加调味汁，用湿生粉勾芡即可', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (95, '粤式油豆腐', '【主料】：油豆腐500g，豆腐皮200g【辅料】：盐半勺，蚝油5匙羹，糖1勺，火麻油2匙羹，酱油5匙羹', '1、准备好食材，将油豆腐切块，豆腐皮切块。喜欢吃小块的，可以切长条小块。2、小火热锅，然后倒入两勺亦舒堂火麻油。3、调至中火，先将油豆腐倒入锅里翻炒，同时放入4匙羹酱油。4、将酱油都炒匀豆腐，即可将豆腐皮倒入锅里，然后到入5匙羹蚝油，翻炒，再加半勺汤，焖2分钟即可。5、装盘出锅~~小诀窍1、油豆腐一般人皆可食用，油豆腐相对于其他豆制品不易消化，经常消化不良、胃肠功能较弱的人慎食。2、里面的糖不能换成蜂蜜，虽然这样会更好吃，但是蜂蜜和豆腐同食可能会引起腹泻。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (96, '陈家太太版粤式藕饼', '猪肉碎适量莲藕取中间一节虾十只葱两根腌料:酱油适量蚝油适量糖适量生油适量生粉适量胡椒粉适量苋汁:蚝油适量白糖适量清水适量生粉适量', '1把猪肉碎用腌料腌好,用保鲜膜包好放进冰箱,等大概一小时2莲藕削皮,打横切成条形后切粒,然后把它们切碎,具体切多碎看本人喜欢什么样的口感,我是喜欢碎一点的3虾去皮,剁成虾容后,用手打到起胶,加入虾仁会令藕饼吃起来更弹牙4葱切粒5把1-4的材料搅在一起,然后把材料捏成一个个球6热锅放油7把藕球放到锅里,(我比较习惯用平底锅煎东西),压成一个个饼状,两边各自煎到金黄色后放入少量的水,基本与藕饼齐平就好,盖上锅盖局到大概水烧干为止.放入水主要是让猪肉快熟一点.如果担心猪肉不够熟,可以加多点水局久一点8把煮好的藕饼上碟,把苋汁倒到锅里煮到粘稠后倒到装好藕饼的碟子上,这样就大功告成了!这个藕饼跟我在广州时候吃过的不一样,广州的酒家做出来的藕饼会下鱼肉而且比较脆,我家的老陈不爱吃鱼,所以我们没有下鱼肉,但是有鱼肉的得把鱼肉打到起胶才好吃.', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (97, '家庭广式叉烧', '主料：五花肉3条。腌肉调料：叉烧酱2大匙、蜂蜜1大匙、蚝油1大匙、生抽1大匙、黑椒粉1/2小匙、白兰地2大匙。碗汁调料：叉烧酱1大匙、蜂蜜1大匙、生抽1大匙、蚝油1大匙、麻油1小匙、清水2大匙、生粉1小匙。', '一、置一大碗，放叉烧酱2大匙、蜂蜜1大匙、蚝油1大匙、生抽1大匙、黑椒粉1/2小匙、白兰地2大匙，搅拌均匀；二、放五花肉入碗，用手搅拌均匀，每条都按摩一下，然后用小刀或利锥均匀的密插肉肉以容易入味，感觉用小刀插比较容易入味些，将插好的肉入密实袋或盒，也将多余的汁倒进去，入冰箱1天或以上；三、到要烤时候，把肉放在锡纸上；四、包好，放入空气炸锅，设置400°F、35~40分钟；五、有烤肉的空当，可以腾出手来做碗汁，置一小碗，放叉烧酱1大匙、蜂蜜1大匙、生抽1大匙、蚝油1大匙、麻油1小匙、清水1/3杯，搅拌均匀；六、时间到后，把肉放入空气炸锅，在肉的全身涂上碗汁；七、设置400°F、4~6分钟直到烤至微焦，再翻转另一面，也涂上碗汁，再烤设置400°F、4~6分钟，烤好后切薄片；八、把剩下的碗汁加上生粉1小匙，搅拌，放在炉上加热，边煮加搅拌，烧到起泡；九、倒在切了片的叉烧上面，可以享用了。Enjoy！小诀窍一、先用锡纸包着烤，是为肉肉能熟透而保持水分；二、家里的烤箱比较大，用电量也大，烤的食物量不多，可以考虑用空气炸锅，如果使用的功能相似的话。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (98, '经典广东菜粤式叉烧', '主材：精猪肉约500克。腌肉调料：李锦记蚝油1.5大匙，李锦记烧烤汁1.5大匙，生抽2大匙，黑椒粉1/2小匙，白兰地1大匙，花椒粉1小匙。烤肉调料：李锦记蚝油0.5大匙，李锦记烧烤汁1大匙，蜂蜜1.5大匙，生抽1大匙，菜油适量。', '一、猪肉改好刀后放入大盆，加蚝油1.5大匙，烧烤汁1.5大匙，生抽2大匙，黑椒粉1/2小匙，白兰地1大匙，花椒粉1小匙，用手抓均匀后用冰锥或尖刀在肉肉扎密些孔，再用手按摩肉块；二、放密实盒入冰箱隔一夜；三、烤前用锡纸包好肉肉；四、放进空气锅，设置400°F，30~40分钟，时间到后解开，观察肉肉是否熟透，把锡纸包里的汤倒出来留用；五、置一碗，加入蚝油0.5大匙，烧烤汁1大匙，蜂蜜1.5大匙，生抽1大匙，调匀；六、锅底喷一层菜油，铺入叉烧肉，表面刷上烤肉调料，设置380°F，先烤约4分钟，看肉面是否够成色，如果成色不够再烤一烤，如果成色过焦，下次就少用1分钟；七、反转肉块另一面，再刷上烤肉调料，操作如上一步骤相同，总之，肉要熟，表面最好够成色，在冷却叉烧时，把锡纸烤肉时的肉汁和刷肉表面剩下的汁倒入小锅搅拌均匀，烧至起泡，关火，叉烧切片码盘，将刚烧过的汁浇在叉烧上面，享用叉烧时就有肉有汁，肉就不显干燥了。搞掂啦！！小诀窍一、叉烧被插孔后要按摩按摩，让肉汁尽量渗入肉里；二、用烤箱也可以，只是温度和功能与空气锅稍有差异，笔者以往也有用烤箱做叉烧的贴；三、先用用锡纸包着肉来烤熟，是为保持肉的水份，不至于口感太柴；四、切叉烧最好用专用的熟食砧板，总之呢，现在说来：话不可以乱讲，生猪肉更不可以乱吃；五、最后叨叨一下，不要买净瘦肉，否则口感比较柴，要买有网纹有少许带膘的肉，但如果您说我要吃梅叉，那就另当别论，还有，听油管子里的星星师傅说，做叉烧最好用玫瑰露酒，笔者找不到，用白兰地代替了。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (99, '广式萝卜糕', '材料：白萝卜2000g粘米粉800g澄粉200g腊肠两条腊肉一条、小虾米50g花生50g盐适量冰糖一块、油适量、白芝麻适量、葱花适量', '制作过程：1、白萝卜去皮后用瓜刨刨成丝2、腊肠、腊肉洗净后切成小颗粒3、锅里放适量的油，把腊肉倒入炒香4、腊肉煸炒出油后放入腊肠、虾米、花生一同煸炒。腊味炒至金黄即可盛起待备用5、煸炒出来的油留下放入蒜头炒香6、将萝卜丝都倒进锅，炒香以后，萝卜水也倒进锅。7、敲碎的冰糖放进萝卜丝一起炒，待糖溶化8、萝卜丝煮软，放入两勺盐，入胡椒粉翻炒均匀后，倒入炒好腊味与萝卜丝翻炒均匀，就可以关火，把粘米粉和澄粉混合一起，加入1100ml的水搅拌均匀成面煳状9、放入锅中蒸40分钟左右10、萝卜糕蒸熟后撒上白芝麻和葱花即可11、取出待凉之后切块，也可以放入不粘锅中煎过，味道更好12、也可以放入不粘锅中煎小会，两面都翻一下，13、煎至金黄，味道更香', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (100, '粤式龙虾', '小活龙虾2只，900克，花生油80克，分成两半，大蒜1头，捣碎，鲜姜1片，切碎，瘦肉末170克，鸡汤235毫升，烹饪用雪梨酒15毫升，酱油15毫升，玉米淀粉8克，红糖5克，鸡蛋2个，打散，葱3棵，切碎', '1.龙虾洗净，肚子朝上拿着。为了沥出虾体内残留的排泄物，需要从其尾巴末端的小孔插一根食扦进去；之后扯下尾巴，切成小片，再将虾钳劈成对半。如果你知道怎么吃龙虾身上的肉，也可以把身子切开放在一起。2.在深煎锅内中火加热一半花生油；放入蒜末炸1分钟；倒进龙虾片炸4-5分钟直到熟透。将龙虾和大蒜捞出装盘并保温。3.在煎锅内热余下的油，加姜末和猪肉末，炒至猪肉变色；加入鸡汤搅拌再烧开。在小碗中倒入雪梨酒、酱油、玉米淀粉和红糖充分搅匀后倒进锅内，翻炒1-2分钟直到酱浓稠但还比较清澈。4.撒上葱花，关火。将打散的鸡蛋浇在锅里调好的料上，搅拌直到鸡蛋成小片状。最后，将龙虾回锅，小火焖几分钟直到入味。盛出装盘，上桌前几分钟要盖上盖。配蒸饭好好享受吧；刚才辛苦了！', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (101, '粤式口水鸡', '三黄鸡半只，生姜，葱头，蒜，葱花，香芹，盐，酱油，芝麻油，蟹黄辣酱，辣椒油', '1、三黄鸡半只洗净备用，汤锅放清水烧开。2、水开后投入几片生姜，然后把半只鸡也放入，中大火煮25－30分钟左右（用筷子从鸡腿最厚处能轻轻插过，并无血水渗出即可），关火后盖盖再焖5分钟左右。3、准备半盆凉开水，再投入适量冰块，把煮好的鸡捞起立即投入冰水中，让其快速冷却，这样能让皮质嫩滑，脆而不腻。4、冰鸡的时间就来准备调料：把适量的生姜和蒜剁成末放入碗里，加入适量的蟹黄辣酱、盐、酱油、芝麻油拌匀。5、盘底可先铺一些香芹粒（根据自己喜好，也可不放），然后捞出冷却好的鸡剁成块，摆放在香芹粒上。6、再把调好的调料浇在鸡块上，再淋上辣椒油，洒上些香芹粒、葱花就可以上桌啦！', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (102, '粤式蛋挞', '原料：盒装千层皮1盒鸡蛋2只牛奶110克炼奶1大匙柠檬汁1/2小匙香草香精1/2小匙盐1/8小匙糖2小匙', '一、用挞模压出面块；二、用手指将面块在挞模里压得均匀，并把溢出多余的边用手指压去；三、在面坯上用牙签扎几个孔，然后放在冰箱（非雪藏层）冷冻约30分钟；四、在冷冻面坯时可腾出手来做蛋液，将蛋打均匀，放牛奶，搅拌均匀，再放炼奶、香精、柠檬汁、盐和糖，搅拌均匀；五、再用网筛将杂质滤去，预热烤箱400F；六、冷冻时间到后取出面坯，倒入混合好的蛋液，七至八成满，不能太满；七、用一大盘盛着挞模，放入预热好的烤箱，325F--350F，烤约15分钟，一定要开箱灯，一旦发现表面发焦，立即取出。小诀窍一、千层酥皮总觉得比较油腻，以前做过用猪油做的，感觉才是真的蛋挞味道，稍觉硬身些，但用盒装的比较方便快速；二、放适量香草香精是为劈去蛋胜味，而且为蛋挞增香；三、放少许柠檬汁是为稳定蛋液，在蒸水蛋或炖蛋时最好也放些，主要是为平衡蛋的酸咸度，据查过资料，鸡蛋带有微量的碱性；四、在做好面坯时放入冰箱冷冻，是为更好的成形；五、用的牛奶要求不高，我们平时喝的盒装或瓶装牛奶皆可，如果不备炼奶，可多加少许糖；六、关于做蛋挞、蒸水蛋，如果想蛋嫩滑而不散，蛋和水的比例1：1-1.2，而且味道咸的比甜的容易凝固，因为盐在中间起凝固作用；七、成熟程度为蛋液刚凝固为炒。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (103, '粤式肠粉', '斋肠：原材料-粉皮粘米粉4汤匙菜油1汤匙玉米淀粉1汤匙水12汤匙原材料-馅：水发云耳1/2杯水发金针1/2杯罐头竹笋1/2杯水发冬菇5只腌渍牛肉75克香葱1根', '斋肠：一、把冬菇切成块、云耳摘成小朵，把水发云耳、金针、冬菇洗净抓干水后放入锅，开中火，煸干水分；二、加入竹笋，再点入精盐约2/3茶匙、糖1/2茶匙、胡椒粉1/2茶匙，炒至材料入味，盛起备用；三、在一较大的碗，倒入粘米粉4汤匙、玉米淀粉1汤匙、油1汤匙和水12汤匙成为粉浆，搅拌均匀；四、用一大锅，把水烧开，用一方烤盘，在方烤盘上涂一层很薄的油，放入沸水面；五、倒入粉浆，不要太多，刚好没过底就可以了；六、等粉浆变得透明，在一边放入炒过的云耳、金针、竹笋和冬菇；七、用铲子慢慢把馅料翻卷好卷后就可以上碟了，再淋上生抽、旁边伴上水焯青菜、撒上葱花即可提供食用，喜欢的可加少许辣椒酱，很棒的。牛肉肠：一、把牛肉切薄片，放生抽1汤匙、盐1/4汤匙、糖1/4茶匙、苏打粉1/4茶匙，用手抓至起粘性，再加2汤匙水，再抓至水完全被吸收，静置30分钟；二、把粉浆搅拌均匀，不要让淀粉沉底；三、用一大锅，把水烧开，取一方烤盘，在方烤盘上涂一层很薄的油，放入沸水面；四、如果担心粉浆铺得不均匀，可用烙饼推子推平；五、等粉浆变得透明，放一边放上牛肉，堆成长条；六、再用铲子卷成卷，盖上锅盖，大火蒸5-10分钟即可上碟，再浇上酱油、麻油，旁边拌白水焯的青菜，撒上葱花，正到痺。小诀窍一、成品图里有两种肠粉，有斋有肉的；二、各种牌子的粘米粉质量可能有少许差别，有调粉浆时先做一盘试，如果太硬，应该酌情加少许水；三、做斋肠时，馅料应预先炒好，等到入馅料后卷好就可以上碟了，不用再蒸；四、做牛肉肠时，牛肉是生的，应该在被粉皮卷好后再蒸熟。五、馅料的材料可以根据自己的喜欢来组合，但做法生熟料有别，如做斋肠与做牛肉肠，，牛肉肠就要多加一道蒸的工序了。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (104, '粤式打边炉', '大白菜1／2棵，水发鱿鱼1尾，肉片200克，虾300克，玉米300克，豆腐1块，青菜1把，鱼饺10个，水晶饺10个，高汤10杯', '1、白菜洗净、切段，同高汤煮10分钟。2、鱿鱼去皮切花刀片，玉米切小段，备齐火锅料后，将锅子盛装1材料置于加热器具上，煮开后放入火锅料即可。蘸酱：沙茶酱、蛋黄、辣椒粉、葱花、花生粉、酱油小诀窍汤锅内不需另加调味料，烹煮时食材会释出咸甜味。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (105, '粤式焗鲈鱼', '加州鲈鱼1条（约重750克），青、红椒料各5克，蒜茸10克，葱花5克，花椒盐适量，吉列粉100克，湿粉5克，净蛋清20克，蛋黄15克，干生粉100克，耗生油75克，绍酒10克。', '1、将鲈鱼治净起鱼肉，留原条骨。将鱼内斜刀切“双飞”片备用。2、将鱼片加精盐1克、蛋清、湿粉拌匀，拍上吉列粉。原条鱼骨连鱼头加精盐1克，蛋黄拌匀，拍上干生粉。3、烧镬落油至210℃，放入鱼骨炸至金黄色至熟捞起放在碟上，然后将鱼片炸至浅金黄色，以熟为度捞起，回收镬中余油，随即放蒜茸、椒粒、葱花爆香，再放炸好的鱼片，烹酒，撒上花椒盐拌匀，铺在鱼骨面上即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 5, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (106, '扬州蛋炒饭', '主料：米饭(蒸)1000克，鸡蛋500克，辅料：鸡肉40克，火腿50克，虾仁5克，干贝15克，鲜香菇25克，鸭肫30克，水发海参25克，冬笋25克，豌豆25克，鸡胸脯肉50克，调料：黄酒15克，小葱15克，猪油50克，盐20克', '1.虾仁洗净，加入适量蛋清、淀粉、清水搅匀上浆；2.干贝用水浸泡，洗净，备用；3.香菇去蒂，洗净；4.鸭肫洗净，煮熟；5.冬笋去皮，洗净，煮熟；6.葱去根须，洗净，切末；7.鸡脯肉洗净，煮熟；8.将海参、鸡肉、火腿、鸭肫、香菇、笋、猪肉均切成小方丁；9.鸡蛋磕入碗内，加精盐20克、葱末5克，搅打均匀；10.将锅置火上，舀入熟猪油75克烧热，放入虾仁滑熟，捞出；11.放入海参丁、鸡丁、火腿丁、干贝、香菇丁、笋丁、鸭肫丁、猪肉丁煸炒，加入黄酒、精盐10克、鸡清汤25毫升，烧沸，盛入碗中作什锦浇头；12.锅置火上，放入熟猪油150克，烧至五成热时，倒入鸡蛋液炒散，加入米饭炒匀，倒入一半浇头，继续炒匀；13.将饭的2/3分装盛入小碗后，将余下的浇头和虾仁、豌豆、葱末10克倒入锅内，同锅中余饭一同炒匀，盛放在碗内盖面即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (107, '水晶肴肉', '原材料家猪前蹄500克调味料食用硝5克、盐50克、胡椒粉5克、葱5克、姜5克', '1、将皮肉分开，肉用盐、硝腌制10小时，取出后用滚水沸去油、硝及盐水，上笼蒸酥，备用；2、用葱姜水将猪皮用小火炖烂，取一不锈钢方形浅盘，将整张炖好的猪皮铺平在底，再将蒸酥的纯精肉放在面上；3、用炖皮的汤调好味，慢慢倒入盘中入冰箱冷冻即可。开心贴士猪皮冻的做法：鲜猪肉皮刮洗净毛和污物，入沸水锅焯后捞出，倒去污水，再放入锅中加水煮开，用小火焖至六成熟捞出，与姜末同放入绞肉机中搅碎，放回锅中旺火煮至浓白汁状，出锅，冷却即成肉皮冻。特别提示要注意硝的用量；熬皮汤时不可开大火沸腾，否则，汤水会混浊不清；尚未结冻之前不要打开食用，因其既不成型又无口感。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (108, '南京盐水鸭', '主料：肥嫩光鸭1只约1500克，料酒l汤匙，食盐130克，葱结2个，姜3片，八角2粒，花椒少许。', '①嫩光鸭斩去小翅和鸭脚掌，再在右翅窝下开约3厘米长的小口，从刀口处取出内脏、拉出气管和食管，用清水冲净，滤干备用。②将炒锅放在火上放入盐、花椒炒热后备用。③用1／2炒热的椒盐从翅下刀口处塞入鸭腹，晃匀，用剩下椒盐的l／2热椒盐擦遍鸭身，再用余下的热椒盐从颈部刀口和鸭嘴塞入鸭颈，然后将鸭放入缸中腌制(夏天2小时，春秋季4小时，冬季6小时)。然后取出挂在通风凉处吹干，用12厘米长的空心芦管插入鸭子肛门内，在翅窝下刀口处放入姜1片、葱结1个、八角1只。④烧滚6杯清水，放入生姜2片、葱结1个、八角1只和料酒，将鸭腿朝上，鸭头朝下放入锅内，盖上锅盖，放在小火上焖20分钟。⑤将鸭拎起，使鸭腹内的汤汁从刀口处漏出，滤干倒入锅内。⑥将鸭放入汤中，使鸭腹内灌入热汤，再放在小火上焖20分钟取出，抽出芦管，放入容器内冷却后。装碟即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (109, '瓜仁西葫芦', '主料：西葫芦500克，辅料：瓜子仁，松子仁调料；盐，鸡精，姜末，葱花，水淀粉，酒泡枸杞', '1、将西葫芦洗净去皮切成片，姜切片，葱切丝，松子仁、瓜子仁过油炸香待用；2、坐锅点火倒入油，至油温三成热时下姜片、葱丝炒香，再放入西葫芦炒匀，加高汤，再依次放入盐、鸡精，大火炒至西葫芦变软时勾芡，倒入泡好的枸杞，撒上松子仁、瓜子仁即可出锅。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (110, '黄泥煨鸡', '主料：活新嫩三黄（黄嘴，黄脚，黄毛）母鸡1只（重约1250克），虾仁，京冬菜，白糖各50克，猪肉丁150克，火腿丁，香菇丁，葱，姜各25克，鸡肫，绍酒，酱油各100克，大虾米16克，味精1克，盐200克，猪网油250克，鲜荷叶4张，熟猪油80克，芝麻油，芝麻酱，葱白段各少许。', '1、将活鸡宰杀，煺尽毛，在翅膀腋下开一个长约3厘米的小口，挖去内脏，切除肛门，洗净晾干，再用刀背拍断鸡脚、翅膀、腿骨、颈骨，放入钵里，加酱油50克、绍酒25克、精盐5克、葱末和姜汁各少许，腌30分钟。2、将鸡肫肝切成片。炒锅上火，放猪油50克，烧至五成热，先下葱段、姜片炒香，再将肫片、虾仁、冬菜末、猪肉丁、火腿丁、香菇丁、大虾米等配料倒入炒和，加酒、酱油各25克，放味精1克、白糖适量，至配料刚熟时起锅倒入碗内。将配料从鸡翅下刀口放入腹内，然后将鸡头塞进开口处。再将葱切成细茸，拌上少许猪油，涂遍鸡身，并用猪网油将鸡包好，再用荷叶包严，用绳子扎成椭圆形。3、将封酒坛的黄泥敲碎，加食盐、绍酒和水拌和成厚糊，放在湿布上（黄泥厚约3．4厘米），在黄泥中间放上捆好的鸡，将湿布四角拎起，把鸡身包紧，然后将湿布揭去，改用废纸包裹。用竹签在泥面上戳一小孔，以供烘烤时排出热气，防止泥层破裂。最后将包好的鸡放进烘箱，用旺火烘烤40分钟，使黄泥烘干取出，用湿泥将小孔涂没，再入烘箱烘烤30分钟后，改用文火煨烤（每隔20分钟翻一次身），共烘煨四五小时即熟。食前先敲掉泥壳，除去小绳和荷叶，将鸡装盘，淋麻油少许，带芝麻酱、葱白段供蘸食。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (111, '蟹子豆腐', '主料：螃蟹350克，辅料：油菜心100克，水发木耳25克，调料：猪油75克，盐4克，料酒15克，小葱3克，姜3克，胡椒粉1克，蚕豆淀粉15克，香油25克', '1.鲜蟹子磨成浆汁加热，使之凝固成豆腐状，即成蟹子“豆腐”；2.将蟹子“豆腐”切成长5厘米、宽2厘米、高0.5厘米的长方块，待用；3.油菜心择洗干净，用沸水焯烫备用；4.姜葱分别洗净，均切成末；5.木耳择洗干净；6.将锅置旺火上，舀入熟猪油，烧至六成热时，投入姜葱末略煸，放入蟹子“豆腐”，轻轻炒几下，加入料酒、鸡清汤150毫升、木耳、精盐，放入菜心，同烧；7.烧沸后用水淀粉勾芡，淋入香油，装盘撒上胡椒粉（白胡椒粉）即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (112, '清炖蟹粉狮子头', '主料：猪助条肉500克，青菜心12棵，蟹粉100克，辅料：干淀粉50克，调料：精盐20克，味精1.5克，葱姜汁15克，绍酒10克', '1)猪肉刮净、出骨、去皮。将肥肉和瘦肉先分别细切粗斩成细粒，用酒、盐、葱姜汁、干淀粉、蟹粉75克拌匀，做成6个大肉圆，将剩余蟹粉分别粘在肉圆上，放在汤里，上笼蒸50分钟，使肉圆中的油脂溢出。2.将切好的青菜心用热油锅煸至呈翠绿色取出。取沙锅一只，锅底安放一块熟肉皮（皮朝上），将煸好的青菜心倒入，再放入蒸好的狮子头和蒸出的汤汁，上面用青菜叶子盖好，盖上锅盖，上火烧滚后，移小火上炖20分钟即成。食用时将青菜叶去掉，放味精，连沙锅上桌。掌握关键：1.猪肉必须肥瘦搭配，不要剁得过细。2.蒸或炖时，必须吃足火候，让肉圆中的油脂自然溢出，溶化在卤汁中，使之肥而不腻。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (113, '炖鳝酥', '主料：鳝鱼1250克，辅料：猪肋条肉（五花肉）75克，调料：黄酒30克，酱油75克，白砂糖9克，葱白5克，姜5克，白皮大蒜60克，花生油90克', '1.将鳝鱼宰杀后，剖腹去内脏，洗净血水，脊背朝下，放在案板上，用刀沿着脊骨从颈部划至尾部，使骨肉分离；2.斩断颈骨，抓住鱼头劈去骨，再斩掉鱼头，切成长6厘米的斜块，洗净，用洁布吸去水；3.猪肉切成片，待用；4.姜切片，葱白切段；5.炒锅放在旺火上烧热，加入花生油，烧至八成热时，放入鳝块，炸至金黄色用漏勺捞出；6.将鳝块、肉片、姜片，葱白段、酱油同放沙锅中，舀入肉清汤（1000克），加黄酒，放在旺火上烧沸后加绵白糖，盖上锅盖，移至小火上炖至鳝肉酥烂；7.炒锅放在旺火上烧热，加入花生油，烧至五成热，放入蒜瓣炸香，倒入沙锅中即成。小诀窍食物相克：鳝鱼：鳝鱼不宜于狗肉、狗血、南瓜、菠菜、红枣同食。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (114, '黄油焖乳鸽', '主料：乳鸽，辅料：胡萝卜，洋葱，芹菜，调料：盐，辣酱油，黄油，胡椒粉，鸡精，料酒，香叶，淀粉，红葡萄酒', '1、将洋葱、芹菜、胡萝卜分别切成碎末放入器皿中，加入盐、辣酱油、胡椒粉、鸡精、红葡萄酒，用手抓出汁后，将乳鸽放入腌制半小时；2、高压锅中加入黄油，放入腌好的鸽子煸炒至表面变色，加适量开水，放入腌制鸽子的蔬菜和少许香叶，盖上盖子压15分钟；3、开盖后先将鸽子取出，锅内汤取出一部分放入炒锅，加入胡椒粉，水淀粉勾芡，放入黄油炒成浓汁淋在鸽子上即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (115, '香橙鸡盏', '主料：鸡腿肉一条，香橙一个柠檬汁，白糖，盐，淀粉，姜末，少许胡椒粉，胡萝卜丁，豌豆几颗', '1、把鸡腿肉切丁，用盐、淀粉抓一下腌15分钟2、把橙子掏空，橙肉榨汁，加柠檬汁、糖、兑成汁备用3、锅中烧旺油，把鸡肉过一下油后捞出4、锅中放油，将姜末炒香，倒入胡萝卜豌豆后再倒入甜酸汁，鸡丁，收汁后盛入橙子中即可', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (116, '枇杷虾', '主料：虾肉（２５０克），肥膘（２５克），火腿（２０克），水冬菇（２０克），青豆（２０克），冬笋（２０克），鸡肉（２０克），青虾（去壳成凤尾虾）（１２只），鸡蛋（３只），精盐（４克），猪油（４０克），菱粉（１２.５克），味精（２克）。', '一、先把虾肉、肥膘斩成茸，加鸡蛋（打匀）、精盐、菱粉、味精调匀作为外皮；再把火腿、冬笋、青豆、冬菇、鸡肉切成细末，稍加一点虾肉拌匀作为馅心。二、取酒盅１２只，每只盅内搽猪油，再把上面的用料分三次放入每只盅内。第一次先把作为外皮用料的一半放入；第二次把馅心用料放在当中；最后将剩下的一半外皮用料全部放入。三、然后上笼蒸，约蒸十分钟后即熟，一只只倒出，稍微凉一下，在每只靠盅底一头戳一个小孔。随手插上一根凤尾虾，再下六成热油锅，用旺火炸五分钟起锅，另外用清汤、菱粉、精盐调卤浇上即好。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (117, '雪花蟹斗', '主料：蟹粉700克，鸡蛋清7只，熟火腿6克，香菜(芫荽)8克，绍酒80克，精盐5克，白糖2克，葱末8克，姜末5克，鸡清汤300克，熟猪油120克，熟猪肥膘丁50克，水淀粉20克，净蟹背壳12只，胡椒粉3克。', '1．净蟹背壳，入沸水锅中煮沸，捞出，晾干，壳背朝下排在盘中；鸡蛋清抽打成泡沫状，放在抹上猪油的盘内，成12垛，用小菱形熟火腿片、芫荽点缀成小花，上笼小汽蒸熟取出。2．炒锅置旺火上烧热，加猪油100克烧热，下葱、姜及肥膘丁，放入蟹粉，轻炒，加绍酒炯透，加鲜汤、精盐、糖烧透，加水淀粉勾芡，浇猪油和匀，撒胡椒粉出锅，分装入壳内，上放雪花垛。3．炒锅放鸡清场150克、精盐l克烧沸，入水淀粉搅匀成琉璃状，加猪油搅和，浇在雪花蟹斗上。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (118, '扬州炒饭', '材料粳米饭150克，鸡蛋1只，葱花10克，小虾仁25克，青豆25克，熟火腿丁25克，熟鸡丁25克调味料味精2克，冷猪油30克，植物油250cc，盐、胡椒粉少许，生粉少许', '1、虾仁洗净后加入盛器中，用蛋清、生粉、盐搅拌上浆。2、用旺火将锅烧热，放入植物油滑锅。3、锅内入油250cc，放入小虾仁过油至熟沥出。4、再放入熟火腿丁、熟鸡丁、青豆过油沥出。5、另起锅，锅内入冷猪油30克，放入打散的蛋液炒至八成熟。6、放入过油的小虾仁、熟火腿丁、熟鸡丁、青豆和米饭炒散、炒匀。7、放入盐、胡椒粉、味精将米饭炒出香味，撒上葱花即可。POINT1、火力不能过小，锅要热。2、盐不能放得太多。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (119, '碧螺春水烧豆腐', '主料：豆腐，碧螺春茶，水发枸杞，精盐，食用油，水淀粉', '1、将碧螺春茶用温开水洗一遍，用沸水泡好待用，豆腐切成块，坐锅点火，倒入水，待水开后放入豆腐块，加适量盐煮3分钟去掉豆腥味；2、坐锅点火倒入油，油热后倒入茶水茶叶，再放入枸杞，豆腐，盐，煮开后用淀粉勾芡即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (120, '冰镇瓜汁血燕', '主料：黄色西瓜肉，血燕，冰糖。', '西瓜榨成汁，过滤后加溶化的冰糖水，发好的血燕用冰糖水过两次，放入小碗中，倒入西瓜汁，放入冰箱中在2℃的温度中放置2小时即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (121, '大烧马鞍桥', '主料：粗活鳝鱼350克，猪腿肉150克。蒜瓣40克，香醋10克，葱15克，姜10克，绍酒乃克，酱油20克，盐3克，糖色5克，白糖15克，芝麻油5克，胡椒粉1克，青蒜丝10克，熟猪油750克（实耗油150克）。', '1、蒜瓣剥去蒜衣，洗净；2、葱洗净，挽结；3、姜洗净，切片；4、青蒜择洗干净，切成丝；5、将鳝鱼宰杀，去内脏，洗净，切成4.5厘米长的段，每段剞2～3刀；6、取锅置旺火，舀入清水，加精盐50克、香醋75克烧沸，放入鳝段略烫，沸后捞出洗净；7、猪肉洗净，切成约4.5厘米的长方形厚片，待用；8、炒锅置旺火上烧热，舀入熟猪油50克，烧至五成热，放入葱结（10克），姜片（5克），再倒入猪肉片，煸炒至肉片变色时，加入酱油（50克）和清水（500毫升），盖上锅盖，烧沸后，用小火焖约30分钟；9、另取炒锅置旺火上，舀入熟猪油l00克，烧至五成热，放入蒜瓣略炸，锅离火，焖约3分钟；10、再置旺火上，捞出蒜瓣，放入葱结10克、姜片5克，投入鳝鱼段翻炒几下，加入香醋5克、酱油50克、精盐5克、料酒、糖色和清水150毫升，烧沸后端离火口；11、将肉片、鳝段一同下入带有竹箅的砂锅中，倒入肉汤和鳝鱼卤汁，加入白糖，盖上锅盖，置旺火上烧沸后再改用小火焖约15分钟，再用旺火收浓汤汁；12、用水淀粉勾芡，淋上香油，撒上胡椒粉（宜用白胡椒粉）、青蒜丝即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (122, '蟹粉狮子头', '主料：猪肋条肉800克，蟹黄50克，蟹肉125克，青菜心200克，虾子1克，清汤500克。', '斩成石榴米状；放碗中，加葱、姜汁、蟹肉、虾子、盐、料酒、淀粉搅拌上劲；青菜心洗净过油码入沙锅内，加肉汤烧开；拌好的肉挤成肉丸，码在菜心上，再点上蟹黄，上盖菜叶，加盖微火焖2小时即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (123, '荷叶粉蒸鸡', '主料：子鸡脯肉，腿肉750克，粳米400克，鲜荷叶4张，猪板油150克，葱结1个，姜片5克，桂皮5克，八角5克，丁香2.5克，白糖25克，绍酒50克，酱油100克，鲜汤100克，麻油50克。', '（1）将鸡肉剁成12块，猪板油切成12块，同放碗内，加姜、葱、绍酒、酱油浸渍半小时。荷叶洗净切成扇面形共14块，去掉背面老筋，放入开水锅略烫，擦干水分。粳米淘洗干净。（2）炒锅置火上，放入粳米、八角、丁香、桂皮炒至金黄色盛起，拣去桂皮、八角、丁香，碾成粗米粉，用粗筛筛去杂质。将粳米粉放入碗内，加鲜汤、酱油、白糖、麻油搅成糊状，将浸渍好的鸡块、猪板油放入糊中拌匀，放入垫有一张荷叶的盘内，上面再盖上一张荷叶上笼蒸30分钟至酥烂取下。将12张荷叶，背面朝上平铺案板，将蒸好的鸡肉平分在荷叶上，包成长方形，整齐地排列在盘中，上笼蒸5分钟取出，抹上麻油即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (124, '鸡茸芦笋', '主料：青芦笋450克，鸡胸肉150克，火腿末1大匙；盐12小匙，香油12小匙；色拉油1大匙，水3大匙，胡椒粉12小匙，盐12小匙；玉米粉1大匙。', '1．芦笋削去梗部硬皮，洗净后交错放入微波炉耐热袋中，加盐和3大匙色拉油拌匀，松绑袋口，以强微波4分钟煮熟后倒置大盘中备用。2．鸡胸肉剁成泥，与色拉油、水、胡椒粉、盐拌匀后放入深碗中，以强微波烹煮2分钟。3．取出鸡肉泥拌入玉米粉、水，以强微波1分钟烹煮，取出搅拌，续以强微波再烹煮2分钟，再取出拌入火腿末及香油淋在芦笋上即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (125, '网包鳜鱼', '主料：鲜活鳜鱼750克，冬菇15克。网油175克，熟火腿末10克，绍酒35克，精盐2.5克，姜汁15克，葱10克，味精1.75克。', '鱼治净，用刀片下鱼肉，修切成12个圆形块，再分别剖斜、直刀纹，然后和鱼头、鱼尾共放碗中，加绍酒、精盐、葱姜汁腌渍。网油洗净沥干，改切成方块，每块网油中间放鱼肉一块，面上再放冬菇一只，包成圆形。将鱼头、尾分放在长腰盘的两端，中间排放包好的鱼块，上笼旺火蒸熟取下，将盘内汤汁滗科炒锅中，置火上烧沸，加味精，用水淀粉勾芡。烧在鱼身上，撤上熟火腿末即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 6, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (126, '黄花菜八宝菜', '主料：十月菜（大头青菜）　辅料：黄花菜、冬笋、木耳、茶干、干胡萝卜丝、干菜梗丝、豆腐皮、白芝麻', '1.干黄花菜，木耳用水泡发，清洗两到三次，沥干水备用；2.将十月菜洗净切丝，其余配料均切成丝备用；3.锅上火放入油，加入姜丝、十月菜丝、黄花菜等炒出香味4.放入调料翻炒均匀，淋香油、撒芝麻出锅装盘即可。小诀窍管小伟黄花菜提示您:黄花菜选用晒干的干菜,色暗黄两头有点发黑的黄花菜才是天然无添加的,黄花菜干菜色金黄,外观非常漂亮的是加工过的黄花菜,大家请注意.', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (127, '古法浙江骨', '加厚骨/肉排骨600g嫩姜10g红辣椒适量（切丝）腌料：盐半小匙胡椒粉1/4茶匙麻油1小匙粟粉1大匙面粉1大匙蛋黄粉1大匙清水4大匙汁料：（拌匀）浙江黑醋6大匙糖4大匙酸梅酱2大匙', '1、排骨斩成约1吋长，加入腌料拌匀，腌数小时或至入味，然后用热油以大火炸至8分熟，捞起备用。2、锅中留一大匙热油，注入混合汁料煮沸，加入姜丝和炸过的排骨，以大火火快手翻炒片刻至收汁，最后加入辣椒丝略炒均匀，即可上桌。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (128, '浙江排骨', '排骨350克,糖1/2tsp,盐1/3tsp,五香粉1/2tsp,鸡粉少许,面粉+生粉各40克,蛋1颗,浙江醋120克,喼汁40克,糖2tsp,盐少许', '1、排骨加腌料，腌20分钟2、热油锅把排骨炸至熟，然后开大火把排骨炸到酥脆，备用3、将酱汁倒入锅里煮沸腾，然后加入排骨，翻炒均匀，用大火煮至酱汁收干，起锅倒入盘中，配搭自己喜欢的装饰，上桌享用。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (129, '浙江酱肉', '五花肉酱油.黄酒.花椒大料.糖', '1，酱油.黄酒.花椒大料.糖煮滚。（汤料要能没着肉，我差不多用了半瓶酱油，半瓶黄酒）2，腿肉或五花肉五斤切块洗干净淋干生水，待汤料冷却浸泡肉两三天，每天翻面。3，泡好的肉晒一天后挂通风处阴干，大概要20天左右。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (130, '浙江大陈润饼卷', '\"春卷皮8张\",\"生菜少许\",\"细米粉4把\",\"金针菇1包\",\"鸡蛋2颗\",\"红萝卜丝少许\",\"豆干丝少许\",\"泡发香菇少许\",\"虾米少许\",\"虾仁少许\",\"泡香菇水1碗\",\"香菇素蚝油适量\",\"胡椒粉适量\"', '1:家中现有材料准备好，准备炒一锅香喷喷的米粉。2:炒米粉的做法请参考(材料不拘，依各人口味)：http://sarah228.pixnet.net/blog/post/146311573:简易自制春卷皮的做法请参考：http://icook.tw/recipes/580204:简单就把材料备齐囉！在制作润饼皮的同时还可以一边煮锅汤来搭配。5:在润饼皮上放上生菜和米粉，然后卷起来吃，别有一番风味呢！6:一边看电视，手里一卷一卷不停的吃，真是过瘾！', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (131, '浙江名菜红豆松糕', '\"糯米粉210g\",\"在来米粉150g\",\"糖粉60g\",\"水150g\",\"红豆沙120g\",\"红绿木瓜丝少许\",\"红豆60g\",\"二砂糖20g\",\"水120g\",', '1:制作蜜红豆：红豆洗净，倒入水中静泡半天或过夜，放入电锅中蒸熟（外锅放二杯水），电锅跳起后放入二砂糖混合，再蒸一次（外锅放一杯水），电锅跳起来后沥干备用。混合米粉：将在来米粉粉、糯米粉、糖粉混合并过筛一次，加入150g的水，用手将黏成团的部分搓散，将较乾和较溼的部分搓匀，搓成一锅松散但稍溼润的米粉。若觉得不够溼润，再追加10g水，搓成松散但更溼润的米粉，并重复加水和搓松米粉至难再搓松（我通常会追加二次水）。过筛米粉：将步骤二的米粉过筛（不要用太细的筛网）。2:混合红豆米粉：将筛过的米粉和蜜红豆混合，混合时要轻轻拌，避免米粉压成块或变得不松，且将黏在红豆上的粉搓掉（若红豆沥不够干时，红豆上的水会和粉黏成团，此时要搓掉搓松）。组合：取一个六吋或二个五吋烤模，在模型内部涂上沙拉油，铺上烤纸。倒入1/3或1/2的红豆米粉，再将搓成条状的红豆沙围成一个圆圈放入模型中，再倒入剩余的红豆米粉，轻轻把表面推平，最后撒上红绿木瓜丝。蒸熟：在电锅内放二杯水，将烤模放入电锅中蒸熟，电锅跳起后脱模，切成喜欢的大小即可享用。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (132, '酸辣手撕茄子', '长条紫皮嫩茄子3个（250g），辣椒酱1茶匙（5ml），蒜茸1/2茶匙（3g），生抽1汤匙（15ml），糖1茶匙（5g），浙江香醋1汤匙（15ml）', '1、茄子上笼大火蒸熟后放凉，手撕成长条状。2、然后加上辣椒酱、蒜茸、生抽、糖及浙江香醋调味。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (133, '猪蹄的卤制（详细版）', '卤水的制作：1选用新鲜生板油（第一次没高汤，选用板油不错），2冰糖（要把冰糖碾碎，最好成小颗粒状），3浙江绍兴老酒或红葡萄酒料包：丁香，草果，肉蔻，白蔻，肉桂，甘草，排草，白芷，花椒，香叶，桂皮，大茴，香砂，小茴，橙皮，砂仁', '准备工作：1、将新鲜板油洗净，切成小块放锅中炼制（锅中可放一些水，防止粘锅）小火加热，炼制板油是要不断搅动。2、油炼制好放到一边晾凉，大概还有6成热时把砸好的冰糖放入，也要不停搅动，直至冰糖全部溶解。3、仔细观察锅中变化，看到锅中冒青烟时停火冷却，加入第一次酒，（酒的用量在3两左右，分两次倒入）接着在继续搅动，再到冒青烟时加入第二次酒（如锅热倒酒一定要注意不要被溅到身上，倒入酒时也许搅动）在炼制到冒青烟即可，加水放入煮锅中最好熬制10小时，熬好把汤里的沫打出。料包的制作：1、丁香，草果，肉蔻，白蔻，肉桂，甘草，排草，白芷，花椒，香叶，桂皮，大茴，香砂，小茴，橙皮，砂仁（要想口味在好点可放入甘松，荜波，凉姜）料包下锅时煮半小时左右，汤中方可有大料味，接着放入生姜大葱，盐和洗净的猪蹄。2、（盐要多放点，汤一定要咸点，否则卤出的菜没盐）卤制45分钟左右端离炉子，焖50分钟即可', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (134, '无锡酱排骨', '猪子排1斤，生抽适量，老抽适量，盐适量，料酒2-3大匙，浙江红醋3大匙，片糖（或红糖）2-3大匙，姜片4片，葱段两颗葱的量，八角两颗，桂皮1小块，干桔皮1小块', '01.材料集合照。02.锅内放入料酒、姜片，大火烧开水，将洗好的排骨放入锅内飞去血水。取出沥干水待用。03.锅内热油，放入姜片，葱段，排骨煎至两面金黄色。（正宗的是炸的哦）04.放入水刚好盖过排骨面，将所有的调料及香料放入锅内。大火烧开后，转小火烧制约40分钟。05.汤汁快烧干了。。即可装盘了。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (135, '糖醋排骨', '小排500克、料酒一汤匙、生抽一汤匙、老抽半汤匙、香醋三汤匙分两次放、糖三汤匙、盐半茶匙、味精半茶匙、芝麻半茶匙、', '1、小排500克焯水后，煮三十分钟，肉汤可以煮面条，别倒掉了。2、用一汤匙料酒，一汤匙生抽，半汤匙老抽，二汤匙香醋（不是白醋）腌渍20分钟。3、捞出洗净控水备用，炸制金黄，油别放多，可以省油，只要翻身的勤就好了。4、锅内放排骨，腌排骨的水，三汤勺白糖（大胆的放糖吧，三汤匙，别怕多）。半碗肉汤大火烧开，调入半茶匙盐提味。5、小火焖十分钟大火收汁，收汁的时候最后加一汤匙香醋，那个酸甜口就出来了。6、临出锅撒葱花芝麻，少许味精。小诀窍1、如何外酥里嫩——煮30分钟，这样再大火热油炸到外面焦黄，就外酥里嫩了。如果用生排骨直接炸，容易老2、为啥要腌渍，因为热锅热油迅速封住了肉外表，做糖醋汁的时候不容易吸收进去，排骨里面有肉腥味3、怎么炸排骨？——大火猛催，反正已经煮了三十分钟，早熟了，所以只要保证外面脆就可以了。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (136, '蜜汁火方', '【蜜汁火方用料】，熟南腿1块500克，白糖莲子50克，松子仁25克，蜂蜜50克，熟猪油150克，糖桂花2.5克，冰糖125克，淡清汤90克，水淀粉30克。', '一、将南腿修成大方块，皮朝下放在砧板上，用刀剞小方块，深度至肥肥膘一半，皮朝下放碗中，加入清水（水平南腿），上笼蒸约2.5小时取出，滗去汤汁，然后再加冰糖、淡清汤，上笼蒸约1小时取出，放入白糖莲子再上笼蒸30分钟，取出滗去卤汁，合入同一盘中；二、将锅置旺火上，舀入熟猪油，烧至五成热，放入松子仁炸至呈金黄色时，取出待用；三、将锅置旺火上，倒入卤汁，加蜂蜜烧沸，用水淀粉勾芡，放入糖桂花搅和，浇在火方上面，再撒上松子仁即成。小诀窍【制作蜜汁火方注意事项】南腿即金华火腿，宜选中峰，用旺火将皮烧糊，入清水中刮洗干净，再下汤锅中煮一开，然后烹如上法，则皮酥可口，若火腿存放己久，外皮干硬，则必须用此法泡制.', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (137, '无锡排骨', '猪排1斤、姜片1大片拍松、葱断适量、八角2粒、桂皮1块', '1、排骨洗净切段，放入锅中，加有姜片和酒的开水中烧开、汆烫3分钟捞出，用清水洗净。2、再下油锅炸黄，捞起后再炸一次。3、炒锅放葱姜蒜略煸，下排骨同炒，然后加入浸过面的水、香料、老抽3匙、味精、片糖1条（或砂糖）、酒1匙、镇江醋2－3匙（我没放醋，放了点番茄酱），烧开后改小火。4、慢火熬40分钟左右，待汁液浓稠肉质松软熄火。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (138, '上汤狮子头', '主料：1000克猪肉糜（我做了10个狮子头，每个100克，很大哈）辅料：黄芽菜叶片8片，荸荠100克（切细粒），鸡蛋1个，面包屑2tbsp，鸡汤1cup调料：姜末1tbsp，葱花2tbsp，黄酒2tbsp，酱油5tbsp，糖2tsp', '1，混合肉糜、荸荠粒、鸡蛋、面包屑、姜末、葱末、黄酒、酱油、糖，搅拌上劲（我是带着手套直接用手来搅拌摔打的）2，黄芽菜叶片去梗留叶片，取6片入沸水汆一下立即取出（为的是让它软，能包狮子头，我只做了6个上汤狮子头，剩余的4个蒸了15分钟成形后放冰箱保存）3，手沾水，取100克肉糜，在双手中摔来摔去摔圆后用黄芽菜叶片包好。剩余的同样做。4，沙锅里垫黄芽菜的白的梗子，然后把包好的狮子头放入沙锅，倒1cup鸡汤，上面再盖上剩余的2片叶子。5，大火烧开后转小火炖3小时左右，这样做出的狮子头嫩如豆腐，入口即化。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (139, '雪菜冬笋', '主料：冬笋200克，芥菜75克，调料：盐2克，味精2克，料酒5克，香油10克，豌豆淀粉5克，花生油75克', '1.冬笋切成滚刀片，放入锅中加清水150克、精盐少许，煮熟入味捞出，冬笋汤倒入碗内；2.雪菜梗切成细末；3.锅烧热，加入熟花生油，放入雪菜末煸炒一下，投入冬笋片一起煸炒；4.下入精盐、味精、鲜笋汤，烧开用湿淀粉勾芡，淋上料酒、麻油翻锅装盘即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (140, '清炖狮子头', '(5个狮子头)原料：（去皮）五花肉500g，冬笋75g，葱2根，姜一小块，糖2小勺，太白粉2小勺，料酒1大勺，蛋清一个，白胡椒一小撮，大白菜叶5片，油菜心5颗，清鸡汤750ml，盐适量', '1、将五花肉入冷冻柜冻3、4个小时，炖好鸡汤待用2、将冬笋切碎成细丁待用，大白菜叶分成菜帮和菜叶3、将葱姜都擦成茸（留下两片姜片待用），用100ml清水浸泡待用4、五花肉冻得半硬时取出，先切成薄片，然后切成细丝，最后切成肉丁5、切好的肉丁再粗粗的剁上几刀6、在肉丁里拌入适量盐、糖、料酒、白胡椒、淀粉和蛋清，先搅拌至发粘7、加入冬笋丁拌匀8、把葱姜水分3次加入到肉里，每次倒入少量葱姜水都要把肉丁向一个方向搅拌，待水分被完全吸收掉再继续加入9、把白菜帮铺在沙锅的底部10、取一坨肉在两个手之间摔打几次，团成大肉丸，放在菜帮上11、每一片菜帮上放一颗狮子头，再将菜叶轻轻覆盖在狮子头上12、将鸡汤烧开后缓缓倒入炖锅，至基本没过狮子头，投入姜片13、在文火上慢2小时，出锅前加盐调味14、捞出煮烂的白菜叶，再加入油菜心煮一分钟即可关火上桌小诀窍1、我用的是真空包装的冬笋，如用新鲜的，需要先汆一下水。也可以把冬笋换成荸荠2、肉一定要切碎，不能剁碎更不能绞碎，用尽量锋利的刀和把肉冻得半硬能稍微降低难度3、切肉时一小块一小块的切，不要一气全部切片切丝，这样到切丁的时候肉就变软，又不好切了4、肉要确保充分吸收进葱姜水，慢慢的一点一点的加水5、鸡汤烧开后再慢慢浇到狮子头上，小心不要破坏狮子头外形。用文火慢炖，汤汁才会清澈', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (141, '双味鸡茸豆腐球', '鸡大胸2块，北豆腐1块，鸡蛋1个，红甜椒，青椒，蚝油适适量，盐，白胡椒粉，鸡精，浙江黄酒，淀粉，面包糠，植物油，泰式甜辣酱（最后的蘸料）', '1.先将鸡脯肉用搅拌机绞成肉茸备用；2.红椒，青椒各切成细丁；3.把绞好的肉茸置于一大碗内，将北豆腐捏成豆腐泥后加入碗内。磕入一个鸡蛋，加适量盐、白胡椒粉、鸡精、少量淀粉，适量黄酒。用筷子顺一个方向搅拌均匀；4.将搅拌好的鸡茸豆腐泥分成两份，一份加入适量切好的青椒丁搅匀。汤锅中放清水待水微微热时，把拌好的鸡茸豆腐泥挤成小球逐个放入，保持中小火，稍待鸡茸豆腐球定型后，转中大火煮开2分钟后关火，此时先不要把球取出，先在汤里泡着（以免风干变色）5.炒锅倒入较多的油，面包糠倒入一较平的盘子里。待油温升至7成热时，将剩下的另一半鸡茸豆腐泥（不加青椒碎）挤成小球，均匀粘上面包糠后顺锅边将球逐个滚入油锅，用中火炸至金黄色时捞出滤油（滤油后可用吸油纸再吸下油^_^健康饮食嘛）；6.将煮好的鸡茸豆腐球捞出滤干水份后和炸好的鸡茸豆腐球一起装盘，并在煮的球上点缀上细红椒丁后这菜即可亮相了。吃的时候蘸泰式甜辣酱或椒盐就成^_^小诀窍豆腐，鸡脯肉脂肪含量都较低哦^_^', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (142, '素烧白萝卜', '白萝卜1根，指天椒2条，蒜肉5瓣，花椒半茶匙调味料：糖、料酒、浙江黑醋各2汤匙，老抽1汤匙，水半杯', '1、白萝卜削皮切片。2、锅里放少许麻油爆香花椒，取出花椒。3、把所有的材料加入锅里，煮至汁液粘稠即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (143, '荷花酥', '点心类——荷花酥荷花酥是浙江杭州著名的汉族小吃。酥层清晰，食之酥松香甜，别有风味。“出淤泥而不染”是人们对荷花高雅洁丽品质的赞誉，用油酥面制成的荷花酥，形似荷花，酥层清晰，观之形美动人，食之酥松香甜，别有风味，是宴席上常用的一种花式中点，给人以美的享受。制作时间：120min、难度4星、人数4人、适应人群：老少皆宜烤箱设定：德普烤箱常规模式165、预热8min、烤制18min水油皮：高筋粉300g、低筋粉200g、糖粉100g、黄油200g、清水150g、红色素适量油酥：低筋面粉400g黄油200g；馅料：红豆沙', '1.将水油皮中的面粉和糖粉过筛后加入搅拌缸内，混合均匀；2.黄油切块软化与清水一起加入，慢速混合均匀；3.快速打至面筋完成阶段，约10-12min，4.分两份，其中一份加入粉色素继续搅拌均匀；5将打好的水油皮保鲜膜覆盖，松弛30min；6.将油酥中的黄油和低筋面粉一并倒入搅拌桶慢速混合均匀；7.快速打至成面团，分割成20g大小，水油皮分成每份30g大小；8.将两个颜色的水油皮分别按压成圆片并包入油酥面团；9.擀开后卷起，松弛10min再擀长卷起，松弛10min；10.两个颜色重叠一起，包入40g的豆沙馅；11.整齐的码入烤盘，用刀在表面切出花瓣，刀口深至能看见内馅；12.将德普嵌入式烤箱调制快热档190度，放最下层烘烤30min；小诀窍小贴士：包豆沙馅的皮要擀薄，否则不易烤熟；荷花酥可以用大豆油炸制；', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (144, '香橙排骨', '\"排骨1斤\",\"香橙1个\",\"糖1茶匙\",\"盐少许\",\"浙江香醋2汤匙\",\"柠檬半个\"', '1:把橙洗净,抹干,将皮刨出并切小粒;橙切开两半,搾汁,柠檬半个搾汁,2:排骨洗净,将橙汁、柠檬汁、香醋、橙皮、盐、糖混合,将一半混合汁放入排骨醃20分钟3:锅中烧热油,半煎炸排骨10~15分钟至熟,捞起再烧热油,将剩下的混合汁下锅烧滚,即把排骨回锅,炒匀上碟。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 7, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (145, '家常闽菜豉香平子鱼', '材料：平子鱼、葱姜蒜、调味料：李锦记风味豆豉酱、生抽、蚝油、鸡精、糖', '做法：一、平子鱼去内脏、腮，洗净，两侧分别斜切两刀；葱切段，姜蒜切片二、锅内坐油，将鱼煸至两面微黄起锅备用三、锅内重新坐油，下姜、蒜片爆香后，加入李锦记风味豆豉酱炒出红油四、放入煸好的鱼，调入蚝油、生抽、糖，加入葱段和适量的水五、大火烧开后改中火稍炖十五分钟，再改大火将汤汁尽量收干，起锅装盘即成', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (146, '闽生果', '主料：花生米（３００克），冻猪油（６０克），白糖（４０克），五香粉（少许），椒盐（少许）', '一、将花生米放在开水里泡一泡后取出，剥去皮，再放入热猪油锅内炸酥，然后取出冷却，但不要炸得过久过老，以免发苦。二、将五香粉、糖、椒盐放在一起拌和；冻猪油与花生米拌和；最后再将这些材料混合拌和即好', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (147, '闽南荫豉蚵', '鲜蚵1/2斤,嫰豆腐1盒,黑豆豉2大匙,蒜仁3粒,姜1小段,辣椒1根,青葱2根,水1/2杯,太白粉水适量,李锦记旧庄特级蚝油2大匙,米酒1大匙,香油1大匙', '1、鲜蚵洗净沥干；豆豉以少量水略冲沥干；蒜拍成蒜末；姜切粗末；辣椒切小圈；青葱切葱花；豆腐切方丁。2、起锅以2大匙爆香豆豉，下姜、蒜末、辣椒炒香，下蚝油炒香，加水煮开，加入豆腐丁盖锅略煮3分钟。3、另以小锅沸水川烫鲜蚵，捞至豆腐锅中，以太白粉水勾芡，滴入香油撒入葱花即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (148, '清蒸武昌鱼', '【食材】武昌鱼1条/香葱2根/生姜3片/味极鲜酱油适量/蜂蜜1勺/福建老酒少许', '1、最好是保持整鱼清蒸，因为家里的锅比较小，所以就将鱼切成三段；2、在鱼身上放上姜片，撒上香葱，最后在鱼身上浇上料酒、酱油和蜂蜜；3、上锅蒸12分钟，打个葱结在鱼出锅前2分钟放在鱼背上。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (149, '炒线面（闽）', '面线，油炸葱花，干扁鱼，胡萝卜丝，卷心菜丝，水发香菇，冬笋丝，鲜虾肉，猪瘦肉丝，味精，白糖，酱油，绍酒', '1.将面线放入油锅中炸至金黄色后捞出。2.锅内上热水，下入面线。3.包芯菜切丝，香菇切丝，胡萝卜切丝。4.扁鱼去皮打成末。5.锅内打底油，下入瘦肉丝、虾肉、包菜丝、冬笋、香菇丝和胡萝卜丝，煸炒。放酱油、高汤，倒入面线，放味精、绍酒，然后将面线捞起.6.锅中加入葱丝，淋入明油，加上剩下的原料，翻炒几下，然后放在面线上，再撒上葱花和干扁鱼末即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (150, '闽南烤鱿鱼', '用料主料：鱿鱼调料：葱、姜、胡椒、料酒、糖、盐、海鲜酱、鸡精、淀粉、食用油用具：竹签', '1．将鱿鱼清洗干净，葱、姜洗净切成末；2．取一器皿放入葱姜末、胡椒、料酒、糖、盐、海鲜酱、鸡精调成汁，鱿鱼用竹签串起来放入调好的汁中腌制20分钟，再裹上淀粉；3．坐锅点火放入油，油热倒入鱿鱼，炸至变色捞出沥干油，再放入锅中炸至金黄色捞出摆入盘中即可。小诀窍特点色泽金黄，味道鲜美。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (151, '闽南啤酒鸭', '鸭肉，姜片，啤酒', '1.把鸭肉、姜片切好洗净待用。2.将鸭肉放入锅中爆油，这个过程中要不断翻炒。之后加入姜片，直到颜色变深。3.将爆炒之后的鸭肉姜片再一起倒入高压锅中，倒入啤酒，高压煮15分钟左右即可开锅食用啦~~~~~~~~~~', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (152, '闽南包菜焖饭', '包菜半个胡萝卜1/3个五花肉1小块熟鱼干2条大米1.5杯酱油1勺葵花籽油适量', '1、包菜切丝清水浸泡清洗。2、胡萝卜刨成丝。3、肉切片。4、熟鱼去骨，掰碎。5、大米陶洗干净。6、热锅，下适量油，先下肉片划炒。7、下包菜和胡萝卜继续翻炒，加酱油一勺，继续翻炒。8、将这些炒过的食材和鱼干一起倒入大米一起搅拌，加入清水。9、插电，45分钟。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (153, '闽南口味阿嬷咸饭', '【食材】大米//花生//鲜肉//腊肉//新鲜香菇//新鲜萝卜//酱油//糖', '1、大米淘洗干净，先加入酱油、糖和清水小浸一会儿；2、花生米事先炸好存放待用；3、鲜肉、腊肉都切成小丁，香菇清洗干净，也切成小丁；4、萝卜去皮，切成小块；5、热锅下少许油，翻炒一下肉丁，再继续翻炒香菇和萝卜；6、最后将食材都放进大米里，一起插电焖煮；7、煮好，盛出来，再撒上炸好的花生米。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (154, '正宗闽南炒米粉', '米粉200g，卷心菜1/8棵，胡萝卜1/4根，豆芽菜50g，韭菜50g，色拉油2汤匙，肉燥酱3汤匙，红葱酥2汤匙，高汤2/5杯，生抽1汤匙，芝麻香油1茶匙，白胡椒粉少许', '1.胡萝卜去皮洗净切丝，韭菜择洗干净沥水切小段2.豆芽菜择洗干净，沥水3.卷心菜洗净沥水切细丝4.将胡萝卜丝、韭菜段、卷心菜丝、豆芽菜放沸水锅中氽烫10秒钟，立刻捞出过凉5.米粉入沸水锅中略烫，快速捞起过凉6.2汤匙色拉油热锅，加入红葱酥、高汤、生抽、芝麻香油、白胡椒粉，煮开7.加入米粉，用筷子翻均匀8.加入氽烫过的蔬菜，翻拌均匀至水分收干，装盘9.淋上肉燥酱拌匀即可', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (155, '[闽南风味] 虾仁猪肉沙茶汤面', '\"虾仁20只\",\"猪肉一份\",\"油面2人份\",\"茼蒿菜酌量\",\"韭菜酌量\",\"沙茶粉2汤匙\",\"花生酱3汤匙\",\"猪骨汤(500毫升)一盒\",\"蒜末酌量\",\"绍兴酒酌量\",\"黑胡椒粉酌量\"', '1:备好材料。猪肉用盐、绍兴酒及黑胡椒粉醃三个小时。2:油面先飞水，去油去杂质。3:热锅下油，放入少许蒜末，把猪肉先炒香，然后放入虾仁，煮至8成熟，盛起备用。4:让后就是煮最重要的汤底了~!首先，把沙茶粉炒香。5:倒入500毫升的猪骨汤一盒，再加5小碗水，煮沸。放入3汤匙花生酱，搅拌均匀。(一边煮一边试试味道，重口味的朋友可以再加些蠔油，令汤底更鲜味。)6:放入飞过水的油面煮1-2分钟，然后放入之前炒过的虾仁和猪肉。7:为了让排盘更好看，我先将煮好的面和虾仁、猪肉盛起。然后，煮茼蒿菜和韭菜。8:把煮好的茼蒿菜和韭菜放在碗里的面上，然后，放上虾仁及猪肉，最后，撒上蒜末，倒入沙茶汤。搞定!', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (156, '福建炒面', '黑轮2条，粗米粉1/2包，洋葱1/2个，韭黄20公克，红萝卜丝20公克，油2大匙，酱油1大匙，蚝油1茶匙，细砂糖1/2茶匙，南洋甜酱油1茶匙，盐1/4茶匙', '1.将干燥粗米粉放入滚水中煮3分钟后熄火焖10分钟取出沖凉沥干；备用。2.洋葱切丝；黑轮切丝；红萝卜切丝；?黄切成10公分的段状；备用。3.取一炒锅烧热待其冒烟后熄火，此时放入2大匙油量润锅后，开大火放入洋葱丝、黑轮丝、红萝卜丝一起略炒30秒。4.继续放入粗米粉并加入盐后，以大火续炒3分钟，再放入剩余的调味料一起炒1分钟，最后放入韭黄略微拌炒即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (157, '福建炒饭', '\"冷饭2碗\",\"带壳虾子3只\",\"鲜干贝3颗\",\"鸡里肌肉2条\",\"鲜香菇1朵\",\"婉豆5片\",\"蒜头2颗\",\"糖1/4茶匙\",\"盐1/4茶匙\",\"米酒1茶匙\",\"太白粉1/2茶匙\",\"水300cc\",\"米酒50cc\",\"鸡蛋1颗\",\"鲜味炒手1/2茶匙\",\"酱油2茶匙\",\"蚝油1茶匙\",\"糖1/2茶匙\",\"胡椒粉少许\",\"香油1茶匙\",\"太白粉水少许\",', '1:把虾子剥除的外壳拿来炼高汤(水300cc+50cc米酒)，煮沸后沥出成为虾高汤2:虾仁切丁，鲜干贝切丁，鲜香菇切丁，碗豆切丁，蒜头切末，鸡里肌肉切丁醃入醃料~3:先将酱汁调味料准备好~(粉红色那碗水是虾高汤，如果没炼高汤，那就准备约300cc水)4:冷饭+1颗蛋+1/2茶匙鸡粉5:搅拌均匀，6:热锅加1大匙油，倒入炒饭至蛋汁熟化，这样饭粒就会颗颗金黄分明~7:我想加些创意变化以增加视觉美观，所以拿一个大汤碗里面再扣一个饭碗~8:将炒好的饭填入大汤碗内压实，等会倒扣比较不易松散~9:准备一个大盘，将填充好的大碗倒扣，先不用拿起大汤碗先放著~10:热锅放1大匙油，依序炒熟鸡肉-香菇-蒜末-虾仁-干贝-碗豆，11:食材熟后加入步骤3的两样酱汁调味料煮开~12:加入太白粉水勾芡，即可起锅装碗~(我是用一个小汤碗装起来，等会要倒入炒饭凹槽比较好操作)13:移除大汤碗与饭碗，就形成有一个凹槽的炒饭模型~14:倒入步骤12的食材，就大功告成囉^^', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (158, '简易粥饭食谱 - 福建炒饭', '\"(共4人份)\",\"2碗白饭–可新鲜或隔夜\",\"80g虾仁\",\"2-3条菜心或芥兰，把叶切掉，茎切粒\",\"1-2粒干瑶柱，浸过夜，用手起丝\",\"1粒冬菇，浸过夜，切粒\",\"适量蒜头，制蒜茸\",\"适量葱粒\",\"2只蛋\",\"虾仁腌料\",\"1汤匙绍兴酒\",\"适量胡椒粉\",\"少许盐\",\"虾仁酱汁\",\"200ml鸡汤\",\"1汤匙豉油\",\"生粉献汁\",\"1汤匙生粉\",\"少许清水（约30ml）\"', '1:用大火把蒜茸，冬菇粒爆香2:加入蔬菜粒，瑶柱丝3:添加虾仁4:炒匀至全熟5:添加虾仁酱汁;打献；备用6:煮鸡蛋7:添加白饭8:彻底炒匀9:把煮好的虾仁汁淋上面10:简易粥饭食谱-福建炒饭11:简易粥饭食谱-福建炒饭', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:54', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (159, '福建虾面', '新鲜面条180克,带壳虾子200克,鹌鹑蛋50克,空心菜50克,豆芽菜120克,蒜头20克,姜5克,辣椒1根5克,葱花和香菜少许,虾头和虾壳数个,猪骨头150克,水800CC', '1、虾子洗净挑去肠泥，烧滚一小锅水川烫猪骨，再以清水冲净骨头杂质。2、蒜头和姜切片.辣椒去籽.空心菜洗净切段.豆芽菜洗净备用。3、炒菜锅里放一大匙油小火爆香蒜片和姜片，飘出蒜香后放虾子，改中火炒熟。4、挑出虾子放凉.剥下来的虾头语虾壳再放回炒菜锅里，并放入清水语处理好的猪骨，盖上锅盖(留一小缝)，以中小火熬30分钟。5、使用滤网筛去猪骨和虾壳等等，就能得到美味虾汤，在放回炉子上，以小火保持煮滚状态。6、烧开一锅水将面条煮到八分熟，捞起，改放到高汤里去煮，让面条吸收虾汤得鲜美，若汤汁不足，请补些清水烧开，以盐巴调味。7、利用煮面水分别快速烫过豆芽灿和空心菜与鹌鹑蛋，再放入面汤，最后洒些辣椒末.葱花及香菜救完成拉。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:55', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (160, '福建炒面', '福建油面，粗米粉，鱿鱼，虾仁，猪肉，椰菜，豆芽，蒜头，葱，大地鱼粉，糖，盐，味精，高汤，辣椒酱', '1、将面条与米粉过冷热河七成熟拿出沥干备用，猪肉切片醃盐、味精与生粉备用。2、鱿鱼切片与虾仁醃生粉水后沥于水备用。3、椰菜切大条过水备用。4、蒜茸、葱切条，热油锅爆香蒜茸，下猪肉爆炒，再下鱿鱼与虾仁微炒后放糖、盐，调味熟后剩出备用。5、热油锅放多点油，爆香蒜茸，先放油面炒香，再下椰菜条微炒，倒进粗米粉，再放大地鱼粉、糖、盐与味精调味然后倒进半碗高汤大火边炒边煮至收汁，下猪肉、鱿鱼、虾仁、椰菜、豆芽与葱条再炒至干燥，放两匙明油快炒即可出菜。小诀窍多放点辣椒酱味道更捧。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:55', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (161, '福建炒饭', '米饭1大碗，虾仁6只，扇贝（带子）6粒，蟹棒2条，鸡肉丁鸡肉丁50克，烧鸭肉50克，红萝卜粒，玉米粒，青豆30克，大蒜粒，姜粒适量，调味料：蚝油1汤匙，盐5克，鸡粉3克，香油少许，生粉1汤匙，油适量', '1.1.虾仁和扇贝洗净，扇贝切小粒，虾仁挑去虾肠和鸡肉丁一起用盐和胡椒粉腌5分钟；2.2.蟹棒切小段，烧鸭肉切丁，鸡蛋打均匀，备用；3.3.锅里放油烧热，放入米饭，炒至米粒松散，加入鸡蛋液，炒均匀；4.4.使所有的米饭都沾上鸡蛋液后，加盐，鸡粉调味，炒均匀，盛在碟子上；5.5.锅里重新放油，烧热，爆香大蒜粒和姜粒，把蒜粒和姜粒拿出来，加入鸡肉丁，烧鸭丁，虾仁，扇贝和蟹棒炒香；6.6.加入红萝卜粒，玉米粒，青豆翻炒均匀，加清水少许煮开后，放盐，鸡粉和蚝油调味，继续煮开，将生粉水放入勾薄芡，勾芡的同时加入一点香油和胡椒粉；7.7.将做法6.均匀地淋在已经炒好的蛋炒饭上即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:55', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (162, '福建小吃--花生汤', '生花生米100g，芋头100g，牛奶200ml，椰浆150ml，白砂糖30g。', '生花生清水浸泡3小时。去皮。高压锅内注入550ml清水，放入去好皮的花生，煮开之后小火压煮45分钟至花生软烂。芋头去皮洗净，入蒸锅蒸制40分钟取出。切成小丁。奶锅内注入200ml牛奶、150ml椰浆、30g白砂糖，小火煮制糖融，拌入煮好的花生和芋头丁，小火煮制牛奶微沸即可。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:55', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (163, '传统福建油饭', '材料:糯米4杯(预先浸半小时)白豆干6块(切小丁)香菇8朵(浸软切片)蚝干1小碗五花肉1小块(切小丁)炸葱3大匙花生适量水4杯调味料:黑酱油适量酱油适量盐少许', '1.花生洗净炒香,白豆干切小丁炸至金黄色备用.(图1-图2)2.烧热适量油,爆香五花肉丁,加入香菇片兜炒,加入蚝干兜炒片刻,再加入炸葱..(图3-图6)3.把预先浸过的糯米加入,再加入调味料炒匀..(图7-图9)4.最后加入水,放入饭煲煮至熟透,开盖加入炸好的白豆干即可..(图10)5.盛在碗上,洒上炒香的花生与炸葱即可享用..(图11)', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:55', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (164, '福建荔枝肉', '主料：瘦猪肉300克，辅料：荸荠100克，调料：大葱15克，红糟50克，白醋10克，酱油10克，白砂糖15克，白皮大蒜5克，蚕豆淀粉10克，味精3克，香油5克，花生油50克', '1.将精肉洗净，切成10×5×1厘米的厚片，再剖上十字花刀，然后再切为3片；2.马蹄（荸荠）切小块，每粒2～3块；3.马蹄块与肉片一起用湿淀粉和剁细的红糟抓匀；4.葱去根须，洗净，取葱白切马蹄葱；5.酱油、白醋、白糖、味精、上汤、湿淀粉调卤汁待用；6.锅置旺火上，下花生油八成热时倒入上浆的肉片和马蹄，用勺扒散，待肉剖花成荔枝状时，用漏勺捞起，沥干油；7.锅留余油，先下蒜末、葱白，煸一下再入卤汁烧沸，随即倒入荔枝肉和马蹄块翻炒几下即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:55', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 1);
INSERT INTO `foods` VALUES (165, '福建绣球干贝', '主料：对虾300克，干贝75克，肥膘肉40克，辅料：荸荠50克，鸡蛋清25克，调料：大葱20克，姜10克，盐5克，料酒15克，蚕豆淀粉10克，味精3克，胡椒粉3克', '1.干贝洗净，放入汤碗内；2.干贝内加入上汤100毫升、葱白10克、生姜，上笼屉旺火蒸1小时；3.蒸好的干贝取出，沥出干贝汁（汁另用），待干贝凉透后，用刀压碎，成干贝丝；4.鲜虾洗净，去头、尾、壳、砂线，用干毛巾吸干水分，剁成泥；5.肥膘肉切小米粒；6.马蹄（荸荠）削头、皮，用刀打碎剁成茸，挤干水分；7.葱白10克切珠；生姜1片切米；8.干贝、虾泥、肉粒、马蹄茸、葱主配料均放在碗中；9.下25克蛋清，加入适量的精盐、料酒，少许味精，胡椒粉，顺一个方向打成虾胶；10.虾胶挤出24个等量的丸子；11.做好的丸子外面滚匀干贝丝，摆在腰盘上，上旺火笼屉蒸15分钟，取出装盘；12.锅置旺火上，倒入上汤200毫升，烧开后加少许味精、湿淀粉勾芡成薄芡，淋在绣球上即成。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:55', 8, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 2, 1);
INSERT INTO `foods` VALUES (166, '辣椒炒肉1', '湖南经典名菜', '菜品简介：\n辣椒炒肉是一道经典的中式家常菜，以其鲜香辣味和简单易做的特点深受大众喜爱。这道菜以猪肉为主料，搭配新鲜的辣椒，通过快火翻炒，使肉质鲜嫩，辣椒脆爽，味道层次丰富，既下饭又开胃。\n\n主要食材：\n猪肉：300克（建议选用瘦肉或五花肉，根据个人喜好）\n青椒：2-3个（可根据辣度选择青椒、尖椒或小米椒）\n红椒：1个（增加色彩和口感）\n大蒜：3瓣\n生姜：1小块\n葱：适量\n调味料：\n生抽：1汤匙\n老抽：1/2汤匙（用于上色）\n料酒：1汤匙\n盐：适量\n白糖：1/2茶匙（提鲜）\n白胡椒粉：少许\n淀粉：1茶匙（用于腌制肉片）\n食用油：适量\n制作步骤：\n准备食材：\n\n猪肉切成薄片，加入生抽、料酒、白胡椒粉、淀粉和少许盐，抓匀腌制10分钟。\n青椒和红椒去籽，切成条状或块状。\n大蒜切片，生姜切丝，葱切段备用。\n热锅凉油：\n\n锅中倒入适量食用油，油热后放入腌制好的肉片，快速翻炒至肉片变色，盛出备用。\n炒辣椒：\n\n锅中留底油，放入蒜片、姜丝爆香，接着加入青椒和红椒，大火翻炒至辣椒略微变软。\n合炒：\n\n将炒好的肉片重新倒入锅中，与辣椒一起翻炒均匀。\n加入老抽调色，调入适量盐和白糖，继续翻炒1-2分钟，使肉片和辣椒充分入味。\n出锅：\n\n最后撒上葱段，翻炒几下即可出锅装盘。\n菜品特点：\n色泽：红绿相间，色泽鲜艳，诱人食欲。\n口感：肉片嫩滑，辣椒脆爽，辣味适中，回味无穷。\n风味：咸鲜微辣，香气扑鼻，适合搭配米饭或面食。\n小贴士：\n如果喜欢更辣的口感，可以选择辣度较高的辣椒，如小米椒或尖椒。\n腌制肉片时加入淀粉可以使肉质更加嫩滑，炒制时不易老。\n炒辣椒时火候要快，保持辣椒的脆爽口感。\n适合人群：\n喜欢辣味菜肴的食客。\n家常便饭或朋友聚餐时的下饭菜。\n营养价值：\n猪肉富含蛋白质和铁质，有助于补充体力。\n辣椒含有丰富的维生素C和辣椒素，具有促进食欲和增强免疫力的作用。\n辣椒炒肉不仅制作简单，而且味道鲜美，是一道适合日常餐桌的经典菜肴。无论是家庭聚餐还是独自享用，都能带来满满的幸福感。', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:55', 3, 3, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 3, 1);
INSERT INTO `foods` VALUES (167, '辣椒炒肉12', '湖南经典美食', '湖南经典美食\r\n湖南经典美食\r\n湖南经典美食湖南经典美食', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', '2025-02-12 05:50:55', 3, 1, 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/6a8b4e1d-678e-4a06-8cad-0cbde357db25_morenfoog.png', 1, 0);
INSERT INTO `ingredients` VALUES (1, '大米', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/cc5c7e80-d9bb-48c5-8218-e4d2c796ec84_morenshicai.png', '亚洲主食，碳水化合物来源', 1, '2025-02-11 10:10:13');
INSERT INTO `ingredients` VALUES (2, '小麦粉', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/cc5c7e80-d9bb-48c5-8218-e4d2c796ec84_morenshicai.png', '面食基础原料，用于包子、面条', 1, '2025-02-11 10:10:13');
INSERT INTO `ingredients` VALUES (3, '意大利面', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/cc5c7e80-d9bb-48c5-8218-e4d2c796ec84_morenshicai.png', '西式主食，需水煮后调味', 1, '2025-02-11 10:10:13');
INSERT INTO `ingredients` VALUES (4, '燕麦片', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/cc5c7e80-d9bb-48c5-8218-e4d2c796ec84_morenshicai.png', '高纤维早餐主食，可冲泡或烘焙', 1, '2025-02-11 10:10:13');
INSERT INTO `ingredients` VALUES (5, '玉米', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/cc5c7e80-d9bb-48c5-8218-e4d2c796ec84_morenshicai.png', '主食或配菜，富含膳食纤维', 1, '2025-02-11 10:10:13');
INSERT INTO `ingredients` VALUES (6, '红薯', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/cc5c7e80-d9bb-48c5-8218-e4d2c796ec84_morenshicai.png', '高纤维主食，可蒸烤或煮粥', 1, '2025-02-11 10:10:13');
INSERT INTO `ingredients` VALUES (7, '藜麦', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/cc5c7e80-d9bb-48c5-8218-e4d2c796ec84_morenshicai.png', '高蛋白谷物，适合沙拉或主食', 1, '2025-02-11 10:10:13');
INSERT INTO `ingredients` VALUES (8, '鸡胸肉', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/cc5c7e80-d9bb-48c5-8218-e4d2c796ec84_morenshicai.png', '低脂高蛋白，健身常用', 1, '2025-02-11 10:10:13');
INSERT INTO `ingredients` VALUES (9, '牛腩', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/cc5c7e80-d9bb-48c5-8218-e4d2c796ec84_morenshicai.png', '适合炖煮，脂肪与筋肉结合', 1, '2025-02-11 10:10:13');
INSERT INTO `ingredients` VALUES (10, '猪里脊', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/cc5c7e80-d9bb-48c5-8218-e4d2c796ec84_morenshicai.png', '肉质嫩滑，适合炒或煎', 1, '2025-02-11 10:10:13');
INSERT INTO `ingredients` VALUES (11, '三文鱼', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/cc5c7e80-d9bb-48c5-8218-e4d2c796ec84_morenshicai.png', '深海鱼，富含Omega-3', 1, '2025-02-11 10:10:13');
INSERT INTO `ingredients` VALUES (12, '虾仁', 'https://code-grade-server-prd.oss-cn-shenzhen.aliyuncs.com/2025-02-13/cc5c7e80-d9bb-48c5-8218-e4d2c796ec84_morenshicai.png', '去壳虾肉，方便烹饪', 1, '2025-02-11 10:10:13');
